var Q35=[
{n:1,q:"En materia de transporte terrestre resulta de aplicación:",o:{a:"La Ley 16/1987 de Ordenación de los Transportes Terrestres.",b:"El Real Decreto 1221/1990 por el que se aprueba el Reglamento de la Ley de Ordenación de los Transportes Terrestre.",c:"La Ley 17/1979 de Transporte Intermodal.",d:"El Real Decreto 997/2000 sobre autorizaciones de transporte por carretera."},correct:"a",why:{a:"La Ley 16/1987 de Ordenación de los Transportes Terrestres es la norma básica aplicable en materia de transporte terrestre en España."}},
{n:2,q:"En el ámbito de la Comunitat Valenciana, la normativa en materia de transportes está constituida por:",o:{a:"La Ley 13/2017 del Taxi.",b:"La Ley 6/2010 de Movilidad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"La Ley 13/2017 del Taxi es la norma autonómica que regula el servicio de taxi en la Comunitat Valenciana, integrando la normativa valenciana de transportes."}},
{n:3,q:"El Estado transfirió a la Comunitat Valenciana determinadas competencias en materia de transporte por medio de...",o:{a:"La Ley 17/1987.",b:"La Ley Orgánica 17/1987.",c:"La Ley 5/1987.",d:"La Ley Orgánica 5/1987."},correct:"d",why:{d:"La Ley Orgánica 5/1987 fue el instrumento mediante el cual el Estado transfirió a las Comunidades Autónomas competencias en materia de transporte, requiriéndose rango de Ley Orgánica para dicho traspaso."}},
{n:4,q:"Por medio de la Ley Orgánica 5/1987, el Estado delegó en las Comunidades Autónomas:",o:{a:"La potestad sancionadora en las infracciones que pudieran detectarse en el transporte por carretera.",b:"La inspección del transporte por carretera.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas"},correct:"c",why:{c:"La LO 5/1987 delegó en las CCAA tanto la potestad sancionadora (a) como la inspección del transporte por carretera (b), siendo ambas afirmaciones correctas."}},
{n:5,q:"En relación con los transportes por carretera y por cable, corresponden al Estado las facultades relativas a:",o:{a:"La inspección de fronteras en los transportes internacionales.",b:"El control de fronteras en los transportes internacionales.",c:"La imposición de sanciones relacionadas con la inspección y control de fronteras en los transportes internacionales.",d:"Todas las funciones descritas en las respuestas anteriores."},correct:"d",why:{d:"Al Estado corresponden todas las facultades mencionadas: inspección de fronteras (a), control de fronteras (b) e imposición de sanciones derivadas de dichas funciones (c) en transportes internacionales."}},
{n:6,q:"El transporte terrestre por carretera es aquel que se realiza en vehículos a motor o conjuntos de vehículos, que circulan sin camino de rodadura fijo y sin medios fijos de captación de energía....",o:{a:"Por toda clase de vías terrestres, urbanas o interurbanas, de carácter público.",b:"Por las vías de carácter privado cuando el transporte sea público.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El transporte terrestre por carretera se realiza tanto por vías terrestres públicas (a) como por vías privadas cuando el transporte sea público (b), siendo ambas afirmaciones correctas."}},
{n:7,q:"Por su naturaleza, los transportes terrestres se clasifican:",o:{a:"En particulares y complementarios.",b:"En regulares, discrecionales y de lanzadera.",c:"En públicos y privados.",d:"En interiores e internacionales."},correct:"c",why:{c:"La Ley 16/1987 clasifica los transportes terrestres por su naturaleza en públicos (por cuenta ajena con retribución) y privados (por cuenta propia o como complemento de la actividad principal)."}},
{n:8,q:"Aquella modalidad de transporte que se lleva a cabo por cuenta ajena, mediante retribución económica, se denomina:",o:{a:"Transporte privado complementario.",b:"Transporte público.",c:"Transporte regular.",d:"Transporte discrecional."},correct:"b",why:{b:"El transporte público es el realizado por cuenta ajena con retribución económica, estando disponible para cualquier persona que cumpla las condiciones establecidas."}},
{n:9,q:"El transporte que se realiza por cuenta propia para satisfacer necesidades particulares o como complemento de otras actividades particulares del mismo titular, se denomina:",o:{a:"Transporte de lanzadera.",b:"Transporte público.",c:"Transporte privado.",d:"Transporte discrecional."},correct:"c",why:{c:"El transporte privado es el realizado por cuenta propia para satisfacer necesidades propias o como complemento de otras actividades, sin conllevar retribución económica por cuenta ajena."}},
{n:10,q:"Los transportes privados se subclasifican:",o:{a:"En privados particulares y privados complementarios.",b:"En privados discrecionales y privados de lanzadera.",c:"En privados regulares y privados discrecionales.",d:"En privados de uso general y privados de uso especial."},correct:"a",why:{a:"Los transportes privados se dividen en particulares (para uso personal o doméstico del titular y sus allegados) y complementarios (transporte que complementa la actividad principal de una empresa)."}},
{n:11,q:"Aquel tipo de transporte que sirve de complemento a las actividades principales de empresas en las que el transporte no es su finalidad principal, se denomina:",o:{a:"Privado particular.",b:"Privado complementario.",c:"Privado discrecional.",d:"Público complementario."},correct:"b",why:{b:"El transporte privado complementario es el realizado por empresas cuya actividad principal no es el transporte, siendo este un complemento necesario de dicha actividad."}},
{n:12,q:"El transporte destinado a satisfacer las necesidades de desplazamiento de carácter personal o doméstico, realizado en vehículos cuyo número de plazas o su capacidad de carga no excedan de los límites reglamentariamente establecidos, se denomina:",o:{a:"Privado particular.",b:"Privado complementario.",c:"Privado discrecional.",d:"Público complementario."},correct:"a",why:{a:"El transporte privado particular está destinado a satisfacer necesidades personales o domésticas en vehículos que no superan los límites reglamentarios de plazas o carga."}},
{n:13,q:"El transporte privado particular es el destinado a satisfacer las necesidades de desplazamiento de carácter personal o doméstico:",o:{a:"Del titular del vehículo y de sus allegados.",b:"Del conductor del vehículo exclusivamente.",c:"Del titular y del propietario del vehículo, exclusivamente.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"El transporte privado particular cubre las necesidades del titular y sus allegados, no quedando limitado exclusivamente al titular ni al conductor del vehículo."}},
{n:14,q:"Según el art.63 de la Ley 16/1987 de Ordenación de los Transportes Terrestres, por razón de su objeto los transportes pueden ser:",o:{a:"De viajeros o de mercancías.",b:"Permanentes, de lanzadera, regulares y discrecionales.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El art.63 de la Ley 16/1987 clasifica los transportes por razón de su objeto en dos categorías: de viajeros y de mercancías."}},
{n:15,q:"Según el art.63 de la Ley 16/1987 de Ordenación de los Transportes Terrestres:",o:{a:"Son transportes de viajeros los dedicados a realizar los desplazamientos de las personas y sus equipajes en vehículos construidos y acondicionados para tal fin.",b:"Son transportes de mercancías los dedicados a realizar desplazamientos de mercancías en vehículos construidos y acondicionados para tal fin.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.63 define correctamente el transporte de viajeros (a) y el de mercancías (b); ambas definiciones son exactas conforme a dicho precepto."}},
{n:16,q:"El transporte que se realiza para desplazar a personas y sus equipajes, en vehículos adecuados a tal fin, se denomina:",o:{a:"Transporte de viajeros.",b:"Transporte de mercancías.",c:"Transporte mixto.",d:"Transporte de lanzadera."},correct:"a",why:{a:"El transporte de viajeros es el dedicado al desplazamiento de personas y sus equipajes en vehículos construidos y acondicionados para tal fin."}},
{n:17,q:"Según el art.64 de la Ley 16/1987 de Ordenación de los Transportes Terrestres, los transportes públicos de viajeros pueden ser:",o:{a:"Particulares o complementarios.",b:"Regulares o discrecionales.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"El art.64 de la Ley 16/1987 clasifica los transportes públicos de viajeros en regulares (con itinerario y horario prefijados) y discrecionales (sin sujeción a itinerario, calendario ni horario)."}},
{n:18,q:"Son transportes regulares de viajeros:",o:{a:"Los que se efectúan dentro de itinerarios preestablecidos y con sujeción a calendarios y horarios prefijados.",b:"Los que se efectúan sin reiteración de itinerario pero con horarios y calendarios prefijados de antemano.",c:"Los que se efectúan dentro de itinerarios preestablecidos, sin sujeción a calendarios ni horarios.",d:"Los que se efectúan sin seguir itinerarios prefijados y sin sujeción a calendarios ni horarios."},correct:"a",why:{a:"Los transportes regulares de viajeros se caracterizan por efectuarse dentro de itinerarios preestablecidos y con sujeción a calendarios y horarios prefijados."}},
{n:19,q:"Según el art.64 de la Ley 16/1987 de Ordenación de los Transportes Terrestres:",o:{a:"Son transportes regulares los que se efectúan dentro de itinerarios preestablecidos, y con sujeción a calendarios y horarios prefijados.",b:"Son transportes discrecionales los que se llevan a cabo sin sujeción a itinerario, calendario ni horario preestablecido.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.64 define correctamente los transportes regulares (a) y los discrecionales (b), siendo ambas afirmaciones exactas conforme a dicho precepto."}},
{n:20,q:"Los transportes regulares de viajeros pueden ser de uso:",o:{a:"General o especial.",b:"Particular, compartido o mixto.",c:"Privado, compartido y especial.",d:"General, compartido, especial y particular."},correct:"a",why:{a:"Los transportes regulares de viajeros se clasifican, por razón de sus usuarios, en de uso general (utilizables por cualquier interesado) y de uso especial (dirigidos a un grupo específico)."}},
{n:21,q:"Respecto a los transportes regulares de viajeros, señale la afirmación correcta:",o:{a:"Son de uso general cuando van dirigidos a satisfacer una demanda general, siendo utilizables por cualquier interesado.",b:"Pueden ser de uso general o de uso especial.",c:"Son de uso especial cuando están destinados a servir a un grupo específico de usuarios, tales como escolares, militares o similares.",d:"Todas las afirmaciones anteriores son correctas."},correct:"d",why:{d:"Todas las afirmaciones son correctas: los de uso general atienden a cualquier interesado (a), pueden ser de uso general o especial (b), y los de uso especial sirven a grupos concretos como escolares o militares (c)."}},
{n:22,q:"Los transportes regulares de viajeros de uso especial:",o:{a:"No están sujetos a las normas generales.",b:"Por razón de su urgencia y repercusión social, están sujetos a normas especiales.",c:"Sirven exclusivamente a un grupo específico de usuarios.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{c:"Los transportes regulares de uso especial se destinan exclusivamente a servir a un grupo específico de usuarios (escolares, militares, trabajadores de una determinada empresa, etc.)."}},
{n:23,q:"Los transportes de viajeros que no están sujetos a itinerario, calendario ni horario preestablecido, se denominan:",o:{a:"Privados complementarios.",b:"Privados particulares.",c:"Discrecionales.",d:"De lanzadera."},correct:"c",why:{c:"Los transportes discrecionales son aquellos que se llevan a cabo sin sujeción a itinerario, calendario ni horario preestablecido, según el art.64 de la Ley 16/1987."}},
{n:24,q:"Los transportes públicos de mercancías por carretera...",o:{a:"Pueden ser regulares o discrecionales.",b:"Serán siempre regulares, aun cuando no se produzca en los mismos una reiteración de itinerario, calendario u horario.",c:"Serán siempre discrecionales, aun cuando se produzca en los mismos una reiteración de itinerario, calendario u horario.",d:"Ninguna de las anteriores respuestas es correcta."},correct:"c",why:{c:"Los transportes públicos de mercancías por carretera tienen siempre carácter discrecional, incluso aunque se produzca reiteración de itinerario, calendario u horario."}},
{n:25,q:"Según el art.65 de la Ley 16/1987 de Ordenación de los Transportes Terrestres, por el ámbito en el que se realicen, los transportes pueden ser:",o:{a:"Nacionales e Internacionales.",b:"Interiores e Internacionales.",c:"Nacionales, Internacionales y Comunitarios.",d:"Nacionales, Internacionales y Autonómicos."},correct:"b",why:{b:"El art.65 clasifica los transportes por su ámbito en interiores (origen y destino en territorio español) e internacionales (cuyo itinerario discurre por territorio extranjero)."}},
{n:26,q:"Los transportes interiores:",o:{a:"Sirven exclusivamente a un grupo específico de usuarios.",b:"Tienen su origen y destino dentro del territorio del estado español, discurriendo como regla general íntegramente dentro de éste.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Los transportes interiores tienen su origen y destino dentro del territorio español, discurriendo con carácter general íntegramente dentro de él, conforme al art.65 de la Ley 16/1987."}},
{n:27,q:"Se denominan transportes internacionales:",o:{a:"Aquellos cuyo itinerario discurre parcialmente por el territorio de estados extranjeros.",b:"Únicamente aquellos cuyo itinerario discurre totalmente por el territorio de estados extranjeros.",c:"Aquellos que discurren por el territorio de más de una Comunidad Autónoma.",d:"Aquellos cuyo origen o destino está en un país de la Unión Europea, siempre y cuando tal país tenga firmado con España un convenio de reciprocidad."},correct:"a",why:{a:"Son transportes internacionales aquellos cuyo itinerario discurre parcialmente —no necesariamente de forma total— por el territorio de estados extranjeros."}},
{n:28,q:"En razón a la especificidad de su objeto y de su régimen jurídico, los transportes pueden clasificarse en:",o:{a:"Permanentes o temporales.",b:"De viajeros o de mercancías.",c:"Ordinarios y especiales.",d:"Públicos y privados."},correct:"c",why:{c:"Por razón de la especificidad de su objeto y régimen jurídico, los transportes se clasifican en ordinarios (regulados por la legislación general) y especiales (sometidos a normas específicas por su peligrosidad, urgencia u otras causas)."}},
{n:29,q:"De conformidad con lo establecido en el art.66 de la Ley 16/1987 de Ordenación de los Transportes Terrestres, en todo caso se considerará transporte especial:",o:{a:"El de mercancías peligrosas.",b:"El de productos perecederos cuyo transporte haya de ser realizado en vehículos bajo temperatura regulada.",c:"El de personas enfermas o accidentadas y el funerario.",d:"Todos los descritos en las respuestas anteriores."},correct:"d",why:{d:"El art.66 de la Ley 16/1987 considera transportes especiales en todo caso: el de mercancías peligrosas (a), el de productos perecederos bajo temperatura regulada (b) y el de personas enfermas o accidentadas y el funerario (c)."}},
{n:30,q:"Son transportes especiales aquellos en los que por razón de su peligrosidad, urgencia, incompatibilidad con otro tipo de transporte, repercusión social, u otras causas similares están sometidos a normas administrativas especiales:",o:{a:"Cierto, pudiendo exigirse para su prestación una autorización específica.",b:"Cierto, siendo preceptiva para su prestación una autorización específica.",c:"Falso, los transportes denominados especiales solo incluyen a los de materias peligrosas.",d:"Falso, los transportes especiales no requieren normas administrativas especiales, salvo en el caso exclusivo de los transportes de mercancías peligrosas."},correct:"a",why:{a:"Es cierto que los transportes especiales están sometidos a normas administrativas especiales, pudiendo —no siendo preceptivo en todo caso— exigirse una autorización específica para su prestación."}},
{n:31,q:"Transportes ordinarios son:",o:{a:"Los dedicados al transporte de personas enfermas y el funerario, entre otros.",b:"Aquellos regulados por la legislación ordinaria del transporte.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Los transportes ordinarios son aquellos regulados por la legislación ordinaria del transporte; el de personas enfermas o el funerario son, por el contrario, transportes especiales."}},
{n:32,q:"Según el art.21 de la Ley 6/2011, de Movilidad de la Comunitat Valenciana, el transporte de viajeros se clasifica en:",o:{a:"El Servicio público de Transporte, entendiendo como tal el ofertado a la ciudadanía, de acuerdo con un calendario y horario previamente establecidos.",b:"El Transporte discrecional de viajeros, que se prestará de acuerdo con la normativa estatal aplicable.",c:"El Servicio de taxi prestado en turismos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El art.21 de la Ley 6/2011 clasifica el transporte de viajeros en: servicio público de transporte (a), transporte discrecional (b) y servicio de taxi (c), siendo las tres modalidades correctas."}},
{n:33,q:"En la clasificación que realiza el art.21 de la Ley 6/2011, de Movilidad de la Comunitat Valenciana, en cuanto al transporte de viajeros, se incluye...",o:{a:"Servicios de taxis y transporte de personas enfermas.",b:"Transporte a la demanda.",c:"Servicios de transporte en vehículos de alta gama.",d:"Transporte reiterado de personas o cosas."},correct:"b",why:{b:"La Ley 6/2011 incluye en su clasificación el transporte a la demanda, modalidad en la que el itinerario y/o el horario depende de las solicitudes previas de los usuarios."}},
{n:34,q:"De acuerdo con lo previsto en la Ley 6/2011, de Movilidad de la Comunitat Valenciana, las bicicletas y vehículos de movilidad personal...",o:{a:"Podrán viajar en los transportes públicos urbanos y en los transportes públicos interurbanos de piso bajo competencia de la Generalitat.",b:"Podrán viajar en los transportes públicos urbanos y en los transportes públicos interurbanos de piso bajo competencia de la Generalitat, siempre que lleven un certificado que garantice la seguridad de su fabricación.",c:"Podrán viajar en los transportes públicos urbanos y en los transportes públicos interurbanos de piso bajo competencia de la Generalitat, siempre que vayan plegados.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"c",why:{c:"La Ley 6/2011 permite el transporte de bicicletas y vehículos de movilidad personal en los transportes públicos urbanos e interurbanos de piso bajo de la Generalitat, con la condición de que vayan plegados."}},
{n:35,q:"De acuerdo con lo previsto en la Ley 6/2011 de Movilidad de la Comunitat Valenciana, el transporte de las bicicletas y vehículos de movilidad personal que viajen en los transportes públicos urbanos y en los transportes públicos interurbanos de piso bajo competencia de la Generalitat ...",o:{a:"Podrá ser limitado por motivos de muy alta ocupación.",b:"Podrá ser limitado por motivos de seguridad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La Ley 6/2011 permite limitar dicho transporte tanto por motivos de muy alta ocupación (a) como por motivos de seguridad (b), siendo ambas causas de limitación válidas."}},
{n:36,q:"De acuerdo con lo dispuesto en la Ley 6/2011, de Movilidad de la Comunitat Valenciana, no tendrán la consideración de transporte de viajeros, a los efectos de esta ley....",o:{a:"Los que se lleven a cabo en curso de una actividad productiva y como complemento de la misma.",b:"Los que se desarrollen en recintos cerrados.",c:"Los que sean consecuencia de necesidades de la población, como consecuencia de crisis humanitarias o sociales.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"No tienen la consideración de transporte de viajeros los que se desarrollen en recintos cerrados, al no concurrir el carácter público y abierto que caracteriza al transporte de viajeros regulado por la Ley 6/2011."}},
{n:37,q:"De acuerdo con lo dispuesto en la Ley 6/2011, de Movilidad de la Comunitat Valenciana, no tendrán la consideración de transporte de viajeros, a los efectos de esta ley....",o:{a:"Los realizados con motivo de espectáculos, festejos o exhibiciones, siempre que estos actos se hallen debidamente autorizados.",b:"Los que se realicen exclusivamente con el carácter de atracción turística.",c:"Los realizados con motivo de la actividad política o sindical.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Los transportes realizados exclusivamente como atracción turística quedan excluidos de la consideración de transporte de viajeros a efectos de la Ley 6/2011 de Movilidad de la Comunitat Valenciana."}},
{n:38,q:"De acuerdo con lo previsto en el art.40 de la Ley 6/2011, de Movilidad de la Comunitat Valenciana tiene la consideración de transporte publico regular de uso especial...",o:{a:"El transporte universitario.",b:"El transporte de personas usuarias de servicios sociales.",c:"El transporte laboral.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El art.40 de la Ley 6/2011 reconoce como transporte público regular de uso especial el universitario (a), el de personas usuarias de servicios sociales (b) y el laboral (c)."}},
{n:39,q:"De acuerdo con lo previsto en el art.40 de la Ley 6/2011, de Movilidad de la Comunitat Valenciana tiene la consideración de transporte publico regular de uso especial...",o:{a:"El transporte escolar.",b:"El transporte de personas usuarias de una determinada instalación de ocio.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.40 de la Ley 6/2011 reconoce como transporte público regular de uso especial tanto el transporte escolar (a) como el de personas usuarias de instalaciones de ocio (b)."}},
{n:40,q:"De acuerdo con lo previsto en la Ley 6/2011, de Movilidad de la Comunitat Valenciana, y en lo que respecta al transporte discrecional de viajeros, indique la respuesta que no es correcta:",o:{a:"Este tipo de transporte debe estar destinado a un colectivo específico de usuarios, aunque excepcionalmente puede llevarse a cabo en modalidad regular.",b:"Este tipo de transporte se prestará de acuerdo con la normativa estatal aplicable.",c:"Este tipo de transporte no debe suponer una oferta permanente de transporte.",d:"Se define en el apartado 2 c), del artículo 21 de esta Ley."},correct:"a",why:{a:"La opción a) es incorrecta: el transporte discrecional no exige estar destinado a un colectivo específico; su característica definitoria es la ausencia de itinerario, calendario y horario prefijados."}},
{n:41,q:"De acuerdo con lo previsto en el artículo 41 bis) de la Ley 6/2011 de Movilidad de la Comunitat Valenciana, el servicio de transporte autorizado o contratado por la autoridad de transporte competente en su correspondiente ámbito territorial, cuando la determinación del itinerario y/o del horario dependa de las solicitudes previas de las personas usuarias, que contratarán el servicio mediante el pago individual por plaza, recibe el nombre de:",o:{a:"Transporte concertado.",b:"Transporte a la demanda.",c:"Transporte intermodal.",d:"Transporte especial."},correct:"b",why:{b:"El transporte a la demanda, regulado en el art.41 bis de la Ley 6/2011, es aquel en que el itinerario y/o el horario depende de las solicitudes previas de los usuarios, quienes contratan el servicio pagando por plaza."}},
{n:42,q:"De acuerdo con lo previsto en el artículo 41 bis) de la Ley 6/2011, de Movilidad de la Comunitat Valenciana, y en lo que respecta al transporte a la demanda, indique la respuesta correcta.",o:{a:"Se circunscribirán al ámbito espacial o a las relaciones de tráfico que se establezcan, determinados por la relación de municipios o núcleos de población diferenciados entre los que se podrá realizar el transporte, favoreciendo la coordinación e intermodalidad con otros modos de transporte público colectivo.",b:"Se prestará conforme a las condiciones establecidas en la autorización administrativa correspondiente.",c:"La autorización administrativa para la prestación de transporte a la demanda podrá otorgarse con carácter general o sólo para días y horas en los que no se produzca coincidencia con los servicios de transporte público regular de viajeros de uso general.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El art.41 bis establece todas estas características del transporte a la demanda: su ámbito espacial (a), que se presta conforme a la autorización administrativa (b) y el régimen de otorgamiento de dicha autorización (c)."}},
{n:43,q:"De acuerdo con lo previsto en el artículo 41 bis) de la Ley 6/2011, de Movilidad de la Comunitat Valenciana, y en lo que respecta al transporte a la demanda, indique la respuesta correcta.",o:{a:"La prestación de servicios de transporte a la demanda se realizará por una persona, física o jurídica, que cuente con título habilitante para la prestación de transporte discrecional de viajeros en las condiciones que en cada caso se determinen y conforme a la normativa que les sea de aplicación.",b:"Las personas usuarias del transporte a la demanda no deberán facilitar sus datos personales para la gestión de las reservas ni identificarse para acceder a los servicios.",c:"La autorización administrativa se otorgará por un plazo máximo de cuatro años.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El art.41 bis exige que el transporte a la demanda sea prestado por personas titulares del título habilitante para el transporte discrecional de viajeros en las condiciones que correspondan."}},
{n:44,q:"Según el art.71 de la Ley 16/1987 de Ordenación de los Transportes Terrestres, los Transportes públicos regulares de viajeros de uso general:",o:{a:"Tienen el carácter de servicio público de titularidad de la Administración.",b:"Pueden ser utilizados, sin discriminación, por cualquier persona que lo desee y que cumpla las condiciones establecidas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.71 establece que los transportes públicos regulares de uso general tienen carácter de servicio público de titularidad administrativa (a) y pueden ser usados sin discriminación por cualquier persona (b)."}},
{n:45,q:"Respecto a los transportes públicos regulares de viajeros de uso general, indique la afirmación incorrecta:",o:{a:"Como regla general se llevará a cabo por la empresa a la que la Administración adjudique el correspondiente contrato de gestión.",b:"Los vehículos destinados a estos transportes no podrán realizar servicios de carácter discrecional.",c:"Cuando la Administración estime que resulta más adecuado para el interés general, podrá optar por la gestión directa del servicio.",d:"Los contratos de gestión se adjudicarán con carácter exclusivo, no pudiendo otorgarse otros que cubran tráficos coincidentes."},correct:"b",why:{b:"La opción b) es incorrecta: los vehículos sí pueden realizar servicios discrecionales, siempre que estén amparados por la correspondiente autorización habilitante."}},
{n:46,q:"Respecto a los transportes públicos regulares de viajeros de uso general, indique la afirmación correcta:",o:{a:"Los vehículos destinados a estos transportes podrán realizar también servicios de carácter discrecional, siempre que estén amparados por la correspondiente autorización habilitante.",b:"Para hacer frente a intensificaciones de tráfico, que no puedan ser atendidas con los vehículos adscritos a la prestación del servicio, podrán utilizarse otros, ya sean del propio contratista o cedidos por otros transportistas.",c:"Las empresas contratistas de los servicios de este tipo de transporte deben disponer de un libro u hojas de reclamaciones en que los usuarios puedan formular sus quejas, de tal forma que éstas puedan ser conocidas por la administración.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Todas las afirmaciones son correctas: posibilidad de servicios discrecionales con autorización (a), refuerzo con vehículos ajenos en intensificaciones (b) y obligación de libro de reclamaciones (c)."}},
{n:47,q:"Los transportes regulares de viajeros de uso especial:",o:{a:"Solo podrán prestarse cuando se cuente con una autorización especial que habilite para ello.",b:"Podrán realizarse utilizando los vehículos de otros transportistas que cuenten con la oportuna autorización, cuando resulten insuficientes los vehículos de la propia empresa",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas afirmaciones son correctas: requieren autorización especial habilitante (a) y pueden reforzarse con vehículos de otros transportistas autorizados cuando los propios sean insuficientes (b)."}},
{n:48,q:"Respecto a la autorización especial habilitante para realizar transportes regulares de viajeros de uso especial, indique la afirmación correcta:",o:{a:"Solo podrá ser otorgada a una persona física o jurídica que previamente sea titular de una autorización de transporte de viajeros prevista en el artículo 42 de la Ley 16/1987 de Ordenación de los Transportes Terrestres.",b:"Dicha autorización será otorgada por la Administración, estando supeditada a que la empresa transportista haya convenido previamente con los usuarios la realización del transporte a través del oportuno contrato o precontrato.",c:"Estas autorizaciones se otorgarán por el plazo a que se refiera el contrato con los usuarios, sin perjuicio de que la administración pueda exigir su visado con una determinada periodicidad.",d:"Todas las afirmaciones descritas son correctas."},correct:"d",why:{d:"Todas las afirmaciones son correctas: requiere ser titular de la autorización del art.42 (a), está supeditada al contrato previo con usuarios (b) y su plazo es el del contrato con los usuarios (c)."}},
{n:49,q:"La realización de transporte público de viajeros y mercancías estará supeditada a la posesión de una autorización que habilite para ello, expedida por:",o:{a:"La Administración del Estado.",b:"La Administración de la Comunidad Autónoma en que se domicilie dicha autorización, cuando esta facultad le haya sido delegada por el Estado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La autorización habilitante puede ser expedida por el Estado (a) o por la Comunidad Autónoma cuando el Estado le haya delegado esa facultad (b), siendo ambas afirmaciones correctas."}},
{n:50,q:"Respecto a la autorización que habilita para realizar transporte público de viajeros y mercancías, señale la afirmación incorrecta:",o:{a:"El plazo máximo de validez de cada una de estas autorizaciones será de cinco años.",b:"El otorgamiento de autorizaciones tendrá carácter reglado, de manera que solo podrán denegarse cuando no se cumplan los requisitos exigidos para ello.",c:"Las autorizaciones se otorgarán sin plazo de duración prefijado pero su validez quedará condicionada a su visado periódico.",d:"Las autorizaciones que no hayan sido visadas dentro del plazo establecido perderán automáticamente su validez."},correct:"a",why:{a:"La opción a) es incorrecta: las autorizaciones no tienen un plazo máximo de 5 años; se otorgan sin plazo prefijado, quedando su validez condicionada al visado periódico."}},
{n:51,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"Cuando los transportes se realicen íntegramente en recintos cerrados, dedicados a actividades distintas del transporte terrestre.",b:"En los transportes que realicen los organismos dependientes de empresas extranjeras.",c:"Para llevar a cabo transportes públicos de mercancías en vehículos cuya MMA sea igual o inferior a 5 TM.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"No es necesario título habilitante cuando los transportes se realicen íntegramente en recintos cerrados dedicados a actividades distintas del transporte terrestre."}},
{n:52,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"Cuando se trate de transportes oficiales.",b:"Cuando se trate de transportes realizados en vehículos de tres ruedas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Los transportes oficiales quedan exentos de la obligación de obtener título habilitante de transporte, conforme a la Ley 16/1987."}},
{n:53,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"En aquellos transportes realizados en vehículos de hasta 2 Tm de MMA.",b:"En los transportes de larga distancia.",c:"En los transportes internacionales que se realicen dentro de la Unión Europea.",d:"En ninguno de los casos anteriores."},correct:"d",why:{d:"Ninguna de las opciones anteriores corresponde a una exención del título habilitante; los transportes en vehículos de hasta 2 Tm, de larga distancia o internacionales en la UE no están por sí solos exentos de autorización."}},
{n:54,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"En el transporte que se desarrolle entre dos empresas del mismo titular, ubicadas en distintos puntos dentro de territorio nacional.",b:"En transportes de mercancías realizados en vehículos de la categoría N1 que utilicen como fuente de energía combustibles alternativos, cuya masa máxima autorizada no sea superior a 2,5 toneladas, siempre que su capacidad de carga útil no se incremente respecto de un vehículo equivalente cuya masa máxima autorizada no sea superior a 2 toneladas.",c:"En los transportes discrecionales de mercancías destinados a satisfacer necesidades básicas de la población.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Están exentos de título habilitante los transportes en vehículos N1 de combustibles alternativos con MMA no superior a 2,5 Tm, siempre que su capacidad de carga no supere la del vehículo equivalente convencional de hasta 2 Tm."}},
{n:55,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"En los transportes privados complementarios.",b:"En los transportes de basuras e inmundicias realizados en vehículos especialmente acondicionados.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Tanto los transportes privados complementarios (a) como los de basuras e inmundicias en vehículos especialmente acondicionados (b) quedan exentos de la obligación de obtener título habilitante."}},
{n:56,q:"No es necesario obtener el correspondiente título habilitante de transporte:",o:{a:"En los transportes fúnebres.",b:"En los transportes de dinero, valores y mercancías preciosas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{d:"Tanto los transportes fúnebres (a) como los de dinero, valores y mercancías preciosas (b) SÍ requieren el correspondiente título habilitante, por lo que la afirmación de que no es necesario es incorrecta."}},
{n:57,q:"No será necesario obtener autorización:",o:{a:"Cuando se trate de transporte de viajeros o mercancías realizado en vehículos cuya velocidad no supere los 60 km/hora.",b:"Cuando se trate de transporte de viajeros o mercancías realizado en vehículos cuya velocidad no supere los 40 km/hora.",c:"Cuando se trate de transporte de viajeros o mercancías realizado en vehículos cuya velocidad no supere los 80 km/hora.",d:"Cuando se trate de transporte de viajeros o mercancías realizado en vehículos cuya velocidad no supere los 90 km/hora."},correct:"b",why:{b:"No es necesaria autorización para los transportes realizados en vehículos cuya velocidad máxima no supere los 40 km/hora."}},
{n:58,q:"No será necesario obtener autorización:",o:{a:"Cuando se trate de transporte realizado en vehículos que lleven unidos de forma permanente una grúa.",b:"Cuando se trate de transporte realizado en vehículos que lleven unidos de forma permanente máquinas o instrumentos.",c:"Cuando se trate de transporte realizado en vehículos que lleven unidos de forma permanente un grupo electrógeno.",d:"En ninguno de los casos descritos en las respuestas anteriores."},correct:"d",why:{d:"Los transportes realizados en vehículos con grúa, maquinaria o grupo electrógeno unidos de forma permanente sí requieren autorización; ninguno de los casos descritos está exento."}},
{n:59,q:"De conformidad con lo dispuesto en el artículo 21 de la Ley 16/1987 de Ordenación de los Transportes terrestres:",o:{a:"En todo transporte público de viajeros, los daños que sufran estos estarán cubiertos por el seguro obligatorio de viajeros.",b:"En los transportes de autobús y autocar, el transportista responderá de las obligaciones establecidas frente a los viajeros, en la medida en que éstas no estén cubiertas íntegramente por el seguro de viajeros, o por cualquier otro seguro.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El art.21 de la Ley 16/1987 establece correctamente tanto la cobertura del seguro obligatorio de viajeros (a) como la responsabilidad complementaria del transportista (b)."}},
{n:60,q:"En el transporte de viajeros por carretera, la responsabilidad de los transportistas por los daños o pérdidas que sufran los equipajes como consecuencia de accidentes se limitan a:",o:{a:"1200 euros/pieza en transportes incluidos en el Reglamento 181/2011 del Parlamento Europeo y del Consejo, y 450 euros/pieza en los demás casos.",b:"450 euros/pieza en transportes incluidos en el Reglamento 181/2011 del Parlamento Europeo y del Consejo, y 1200 euros/pieza en los demás casos.",c:"1000 euros/pieza en transportes incluidos en el Reglamento 181/2011 del Parlamento Europeo y del Consejo, y 650 euros/pieza en los demás casos.",d:"650 euros/pieza en transportes incluidos en el Reglamento 181/2011 del Parlamento Europeo y del Consejo, y 1000 euros/pieza en los demás casos."},correct:"a",why:{a:"La responsabilidad del transportista se limita a 1.200 euros/pieza en transportes del Reglamento 181/2011 y a 450 euros/pieza en los demás casos."}},
{n:61,q:"En el transporte de viajeros por carretera, la vigilancia de bultos de mano corresponderá:",o:{a:"A la empresa transportista, que será responsable de la pérdida o deterioro de esos bultos producidos durante el trayecto.",b:"Al viajero al que acompañan, siendo por su cuenta los daños que sufran mientras se encuentren a bordo del vehículo.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"La vigilancia de los bultos de mano corresponde al propio viajero, siendo por su cuenta los daños que puedan sufrir mientras se encuentren a bordo del vehículo."}},
{n:62,q:"En el transporte de viajeros por carretera, la empresa transportista es responsable de la pérdida o deterioro de equipajes y bultos de mano:",o:{a:"Siempre.",b:"Si se produce con ocasión de una parada, en la que todos los ocupantes hayan abandonado el vehículo, sin que, inmediatamente después, el conductor hubiera cerrado las puertas del mismo.",c:"Solo si se produce por negligencia del conductor o responsable que debe vigilar dichos bultos.",d:"Todas las respuestas anteriores son incorrecta."},correct:"b",why:{b:"La empresa transportista responde de la pérdida o deterioro de equipajes y bultos de mano cuando esto ocurra en una parada en la que todos los ocupantes hayan abandonado el vehículo sin que el conductor cerrara las puertas."}},
{n:63,q:"Los conductores de los vehículos destinados al transporte por carretera:",o:{a:"Deberán estar en posesión de un certificado de aptitud profesional que será emitido por las autoridades encargadas de expedir las autorizaciones de transporte por carretera.",b:"Tienen prohibido conducir con una tasa de alcohol superior a 0,3 gramos por litro de sangre o su equivalente, es decir 0,15 milígramos de alcohol por litro de aire espirado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas afirmaciones son correctas: los conductores de transporte por carretera deben poseer el certificado de aptitud profesional (a) y tienen la prohibición de conducir con tasas de alcohol superiores al límite indicado (b)."}},
{n:64,q:"Los conductores de los vehículos destinados al transporte por carretera deberán estar en posesión de un certificado de aptitud profesional y una tarjeta de cualificación:",o:{a:"De acuerdo con el modelo del anexo VI del Real Decreto 284/2021.",b:"De acuerdo con el modelo del anexo IV del Real Decreto 1032/2007.",c:"De acuerdo con el modelo del anexo VI de la Ley 16/1987.",d:"De acuerdo con el modelo del anexo IV de la Ley 16/1987"},correct:"a",why:{a:"El certificado de aptitud profesional y la tarjeta de cualificación de los conductores de transporte por carretera deben ajustarse al modelo del anexo VI del Real Decreto 284/2021."}},
{n:65,q:"Según lo dispuesto en el Reglamento UE 165/2014 del Parlamento Europeo y del Consejo, el aparato instalado en vehículos de transporte por carretera para visualizar, registrar, imprimir, almacenar y enviar de manera automática o semiautomática datos acerca de la marcha, incluida la velocidad de dichos vehículos, así como determinados periodos de actividad de sus conductores, se denomina:",o:{a:"Tacómetro.",b:"Tacógrafo.",c:"Velocímetro.",d:"Computador de abordo."},correct:"b",why:{b:"El Reglamento UE 165/2014 define el tacógrafo como el aparato instalado en los vehículos de transporte que registra, almacena y transmite datos sobre la marcha del vehículo y la actividad del conductor."}},
{n:66,q:"El tacógrafo de un vehículo registra:",o:{a:"El estado físico del conductor.",b:"El estado psíquico del conductor.",c:"La frecuencia de combustión del motor del vehículo.",d:"La distancia recorrida por el vehículo."},correct:"d",why:{d:"El tacógrafo registra principalmente la distancia recorrida por el vehículo, su velocidad y los periodos de actividad del conductor; no registra estados físicos ni psíquicos del conductor."}},
{n:67,q:"El tacógrafo de un vehículo de transporte:",o:{a:"Debe estar homologado.",b:"Debe ser instalado por un taller o instalador autorizado.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El tacógrafo debe estar homologado (a) y ser instalado por un taller o instalador autorizado (b), siendo ambos requisitos obligatorios conforme al Reglamento UE 165/2014."}},
{n:68,q:"Los tacógrafos deben estar homologados y se habrán de instalar en el vehículo por taller o instalador autorizado, debiendo llevar una placa:",o:{a:"Que será indeleble y deberá permanecer siempre legible.",b:"Que será circular y tendrá un diámetro de 20 centímetros.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"La placa del tacógrafo debe ser indeleble y permanecer siempre legible; no existe el requisito de que sea circular ni de 20 cm de diámetro."}},
{n:69,q:"Los tacógrafos homologados podrán ser de tipo:",o:{a:"Abierto, cerrado o de frecuencia.",b:"Digital, sincronizado o de frecuencia.",c:"Analógico, digital o inteligente.",d:"Analógico, sincronizado o de frecuencia temporal."},correct:"c",why:{c:"El Reglamento UE 165/2014 establece tres tipos de tacógrafos homologados: analógico, digital e inteligente."}},
{n:70,q:"Los tacógrafos que emplean una hoja de registro, concebida y preparada para recibir y conservar los datos registrados son de tipo.",o:{a:"Digital.",b:"Analógico.",c:"Inteligente.",d:"De frecuencia temporal o sincronizado."},correct:"b",why:{b:"El tacógrafo analógico es el que emplea una hoja de registro (disco) para recibir y conservar los datos que inscriben sus dispositivos marcadores."}},
{n:71,q:"Los tacógrafos que emplean una tarjeta inteligente que permite la identificación de quien la posee, así como la transferencia y almacenamiento de datos, son de tipo.",o:{a:"Analógico.",b:"Digital.",c:"Inteligente.",d:"De frecuencia temporal o sincronizado."},correct:"b",why:{b:"El tacógrafo digital utiliza tarjeta inteligente para identificar al portador y almacenar y transferir datos de actividad del conductor."}},
{n:72,q:"Graban automáticamente la distancia y la velocidad del vehículo, así como el punto de partida y el destino final, permitiendo el control remoto de los datos:",o:{a:"Los tacógrafos analógicos.",b:"Los tacógrafos inteligentes.",c:"Los tacógrafos digitales.",d:"Los tacógrafos de frecuencias temporales o sincronizadas."},correct:"b",why:{b:"Los tacógrafos inteligentes graban automáticamente la distancia, velocidad, punto de partida y destino final del vehículo, y permiten el control remoto de los datos registrados."}},
{n:73,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, la tarjeta inteligente utilizada con el tacógrafo que permite la identificación por dicho tacógrafo de la función de quien la posee, así como la transferencia y almacenamiento de datos, se denomina:",o:{a:"Hoja de registro.",b:"Tarjeta de tacógrafo.",c:"Tarjeta de conductor.",d:"Tarjeta de control."},correct:"b",why:{b:"La tarjeta de tacógrafo es la tarjeta inteligente que permite al tacógrafo identificar la función de quien la posee y facilita la transferencia y almacenamiento de datos."}},
{n:74,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, la hoja concebida para recibir y conservar datos registrados que se coloca en un tacógrafo analógico, y en la cual los dispositivos marcadores de dicho tacógrafo inscriben de manera ininterrumpida la información que procede consignar, se denomina:",o:{a:"Hoja de registro.",b:"Tarjeta de tacógrafo.",c:"Tarjeta de conductor.",d:"Tarjeta de control."},correct:"a",why:{a:"La hoja de registro es el soporte físico (disco) del tacógrafo analógico en el que los dispositivos marcadores inscriben de forma ininterrumpida los datos de actividad del vehículo."}},
{n:75,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, la tarjeta de tacógrafo expedida por las autoridades de un Estado miembro a una autoridad nacional de control competente, que identifica a dicho organismo y, de manera opcional, también al controlador, y que permite acceder a la información almacenada en la memoria de datos o en las tarjetas de conductor y, de manera opcional, en las tarjetas de taller con fines de lectura, impresión y/o transferencia de datos, se denomina:",o:{a:"Hoja de registro.",b:"Tarjeta de tacógrafo.",c:"Tarjeta de conductor.",d:"Tarjeta de control."},correct:"d",why:{d:"La tarjeta de control es la expedida a la autoridad nacional de control competente; permite identificar al organismo controlador y acceder a los datos almacenados en el tacógrafo."}},
{n:76,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, la tarjeta de tacógrafo expedida por las autoridades de un Estado miembro a un conductor concreto, que identifica a este último y permite almacenar los datos de su actividad, se denomina:",o:{a:"Hoja de registro.",b:"Tarjeta de tacógrafo.",c:"Tarjeta de conductor.",d:"Tarjeta de control."},correct:"c",why:{c:"La tarjeta de conductor es la expedida personalmente a un conductor concreto; le identifica y permite almacenar los datos de su actividad en el tacógrafo digital."}},
{n:77,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, el tacógrafo digital debe registrar:",o:{a:"Distancia recorrida y velocidad del vehículo.",b:"Medida del tiempo.",c:"Identidad del conductor.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El tacógrafo digital debe registrar la distancia recorrida y velocidad (a), la medida del tiempo (b) y la identidad del conductor (c), entre otros datos."}},
{n:78,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, el tacógrafo digital debe registrar:",o:{a:"Datos relativos al control, calibrado y reparación del tacógrafo, incluida la identidad del taller.",b:"Incidentes y fallos.",c:"Actividad del conductor.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El tacógrafo digital debe registrar los datos de control, calibrado y reparación con identidad del taller (a), incidentes y fallos (b) y la actividad del conductor (c)."}},
{n:79,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, el tacógrafo analógico debe registrar:",o:{a:"Datos relativos al control, calibrado y reparación del tacógrafo, incluida la identidad del taller.",b:"Actividad del conductor.",c:"Incidentes y fallos.",d:"Identidad del conductor."},correct:"b",why:{b:"El tacógrafo analógico debe registrar la actividad del conductor; los datos de control y calibrado con identidad del taller y los incidentes y fallos corresponden al tacógrafo digital."}},
{n:80,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, y en lo que respecta al tacógrafo inteligente, indique la respuesta correcta.",o:{a:"Los vehículos matriculados por primera vez 36 meses después de la entrada en vigor de las disposiciones específicas indicadas en el artículo 11 de este Reglamento, estarán dotados de un tacógrafo conectado a un sistema de posicionamiento basado en un sistema de navegación por satélite.",b:"Los datos de posición que tienen que ser almacenados temporalmente para permitir el registro automático de los puntos mencionados o para corroborar los sensores de movimiento no serán accesibles a ningún usuario y serán automáticamente borrados una vez que ya no se requieran para dichos fines.",c:"Las empresas de transporte que utilizan vehículos serán responsables de informar a los conductores de la posibilidad de la comunicación a distancia a efectos de detección temprana de una posible manipulación o utilización indebida de los tacógrafos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones sobre el tacógrafo inteligente son correctas: el plazo de 36 meses (a), la gestión de datos de posición (b) y la responsabilidad de las empresas de informar a los conductores (c)."}},
{n:81,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, y con respecto a los tacógrafos inteligentes, para facilitar la comprobación de la observancia de la legislación pertinente, se registrará la posición del vehículo automáticamente ...",o:{a:"En el lugar de inicio del periodo de trabajo diario.",b:"Cada tres horas de tiempo de conducción acumulado.",c:"En el lugar de finalización del periodo de trabajo diario.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El tacógrafo inteligente registra automáticamente la posición del vehículo al inicio del periodo de trabajo (a), cada tres horas de conducción acumulada (b) y al finalizar el periodo de trabajo (c)."}},
{n:82,q:"El conductor de un vehículo equipado de un tacógrafo analógico deberá indicar en su hoja de registro...",o:{a:"El número de su permiso de conducir.",b:"Los kilómetros que figuran en la lectura del cuentakilómetros, al comienzo y al final del viaje.",c:"El tipo de carga transportada, o en su defecto la condición de vehículo vacío.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"El conductor con tacógrafo analógico debe anotar en la hoja de registro los kilómetros del cuentakilómetros al inicio y al final del viaje."}},
{n:83,q:"El conductor de un vehículo equipado de un tacógrafo analógico deberá indicar en su hoja de registro...",o:{a:"Su nombre y apellidos.",b:"La fecha y lugar donde se empiece y termine de utilizar la hoja de registro;",c:"El número de matrícula de cada vehículo en el cual el conductor haya estado destinado, tanto al principio del primer viaje registrado en la hoja de registro como, en caso de cambio de vehículo, durante la utilización de dicha hoja.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El conductor debe indicar en la hoja de registro su nombre (a), la fecha y lugar de uso de la hoja (b) y la matrícula del vehículo o vehículos utilizados (c)."}},
{n:84,q:"Según lo dispuesto en el Reglamento UE 165/2014, del Parlamento Europeo y del Consejo, cuando un conductor lleve un vehículo equipado con un tacógrafo analógico, deberá estar en condiciones de presentar, a requerimiento de un controlador autorizado:",o:{a:"Las hojas de registro del día en curso y las utilizadas por el conductor en los 90 días anteriores.",b:"La tarjeta de conductor, en el caso de que posea una.",c:"Cualquier registro manual o documento impreso realizados durante el día en curso y los 60 días anteriores conforme a lo dispuesto por el presente Reglamento.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"El conductor con tacógrafo analógico debe presentar, si la posee, la tarjeta de conductor; las hojas deben ser del día en curso y los 28 días anteriores, no 90."}},
{n:85,q:"Los conductores de vehículos de transporte no pueden superar los tiempos de conducción máximos fijados:",o:{a:"En el Reglamento CE 363/2012 del Parlamento Europeo y del Consejo.",b:"En el Reglamento CE 561/2006 del Parlamento Europeo y del Consejo.",c:"En el Reglamento CE 363/2006 del Parlamento Europeo y del Consejo.",d:"En el Reglamento CE 561/2012 del Parlamento Europeo y del Consejo."},correct:"b",why:{b:"Los tiempos máximos de conducción están regulados en el Reglamento CE 561/2006 del Parlamento Europeo y del Consejo."}},
{n:86,q:"De acuerdo con lo previsto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes realizados mediante:",o:{a:"Vehículos destinados al transporte regular de viajeros, cuyo trayecto no supere los 50 Km.",b:"Vehículos destinados al transporte regular de viajeros, cuyo trayecto no supere los 60 Km.",c:"Vehículos destinados al transporte regular de viajeros, cuyo trayecto no supere los 70 Km.",d:"Vehículos destinados al transporte regular de viajeros, cuyo trayecto no supere los 80 Km."},correct:"a",why:{a:"Están exentos de instalar tacógrafo los vehículos de transporte regular de viajeros cuyo trayecto no supere los 50 km, conforme al Reglamento CE 561/2006."}},
{n:87,q:"De acuerdo con lo previsto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes realizados mediante:",o:{a:"Vehículos cuya velocidad no supere los 70 km/hora.",b:"Vehículos cuya velocidad no supere los 40 km/hora.",c:"Vehículos cuya velocidad no supere los 50 km/hora.",d:"Vehículos cuya velocidad no supere los 60 km/hora."},correct:"b",why:{b:"Están exentos de instalar tacógrafo los vehículos cuya velocidad máxima no supere los 40 km/hora, conforme al Reglamento CE 561/2006."}},
{n:88,q:"De acuerdo con lo previsto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes realizados mediante:",o:{a:"Vehículos especializados en la reparación de averías, cuyo radio de acción sea de hasta 100 Km alrededor de su centro de explotación.",b:"Vehículos especializados en la reparación de averías, cuyo radio de acción sea de hasta 150 Km alrededor de su centro de explotación.",c:"Vehículos especializados en la reparación de averías, cuyo radio de acción sea de hasta 200 Km alrededor de su centro de explotación.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"Los vehículos especializados en reparación de averías están exentos de tacógrafo cuando su radio de acción sea de hasta 100 km alrededor de su centro de explotación."}},
{n:89,q:"De acuerdo con lo previsto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes realizados mediante:",o:{a:"Vehículos de las Fuerzas Armadas, Bomberos y Cuerpos de Seguridad.",b:"Vehículos utilizados en el transporte no comercial de ayuda humanitaria y vehículos especiales utilizados con fines médicos.",c:"Vehículos con MMA no superior a 7,5 Tm utilizados para el transporte no comercial de mercancías.",d:"Ninguno de los vehículos descritos en las respuestas anteriores."},correct:"d",why:{d:"Ninguna de las opciones corresponde a una exención del Reglamento CE 561/2006; los vehículos de Fuerzas Armadas, humanitarios o de menos de 7,5 Tm sin uso comercial sí están exentos, pero con condiciones distintas a las descritas."}},
{n:90,q:"De acuerdo con lo dispuesto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes...",o:{a:"Que se realicen con ocasión de la impartición de clases prácticas destinadas a la obtención del permiso de conducción o certificado CAP.",b:"Que se realicen en vehículos históricos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Están exentos de tacógrafo los transportes para clases prácticas de obtención del permiso o CAP (a) y los realizados en vehículos históricos (b)."}},
{n:91,q:"De acuerdo con lo dispuesto en el Reglamento CE 561/2006, no están obligados a instalar tacógrafo los transportes...",o:{a:"Que se utilicen en el transporte no comercial de ayuda humanitaria.",b:"Realizados con fines médicos o de comercio de productos sanitarios.",c:"Que se lleven a cabo entre dos países de la Unión Europea que hayan suscrito el correspondiente convenio bilateral que garantice la libertad de residencia y circulación, en sus respectivos ámbitos.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El Reglamento CE 561/2006 exime de tacógrafo a los vehículos utilizados en el transporte no comercial de ayuda humanitaria."}},
{n:92,q:"De acuerdo con lo dispuesto en el Real Decreto 640/2007, están excluidos de la instalación y uso del tacógrafo...",o:{a:"Los transportes oficiales y de empresas dedicadas a la importación de productos energéticos e informáticos.",b:"Los transportes que se utilicen por el servicio postal, siempre y cuando no superen las 7,5 Tm y se realicen en un radio de 50 Km alrededor del centro empresarial; y siempre que la conducción no constituya la actividad principal del conductor.",c:"Los transportes de mercancías de carácter privado complementario, realizados por empresas agrícolas, hortícolas, forestales, ganaderas o pesqueras.",d:"Todas las respuestas anteriores son correctas."},correct:"c",why:{c:"El RD 640/2007 excluye del tacógrafo los transportes de mercancías privado complementarios realizados por empresas agrícolas, hortícolas, forestales, ganaderas o pesqueras."}},
{n:93,q:"Según el art.2 del Real Decreto 640/2007, no será obligatorio el cumplimiento de las obligaciones impuestas en la normativa europea, en relación con la instalación y uso del tacógrafo y los tiempos de conducción y descanso de los conductores, durante la realización de:",o:{a:"Transportes Oficiales.",b:"Transportes del Servicio Postal con MMA no superior a 7,5 Tm, que se realicen en un radio de 50 Km alrededor del centro empresarial.",c:"Transportes en vehículos destinados al mantenimiento de servicios (agua, gas, electricidad, carreteras, teléfonos, radiodifusión, etc.).",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres modalidades citadas (transportes oficiales, servicio postal en las condiciones indicadas y mantenimiento de servicios) están exentas conforme al art.2 del RD 640/2007."}},
{n:94,q:"Según el art.2 del Real Decreto 640/2007, no será obligatorio el cumplimiento de las obligaciones impuestas en la normativa europea, en relación con la instalación y uso del tacógrafo y los tiempos de conducción y descanso de los conductores, durante la realización de:",o:{a:"Transportes de mercancías de carácter privado complementario, realizados en un radio de 100 km alrededor de la empresa, o destinados a actividades agrícolas o forestales.",b:"Transportes de recogida de leche en granjas, realizados en un radio de 100 km desde el centro de explotación.",c:"Transportes de animales vivos entre granjas, o entre éstas y mercados o mataderos, siempre que la distancia en línea recta, entre ellos, no sea superior a 100 km.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres modalidades descritas están exentas conforme al art.2 del RD 640/2007: transporte privado complementario agrícola en 100 km (a), recogida de leche en granjas en 100 km (b) y animales vivos en 100 km (c)."}},
{n:95,q:"Según el art.2 del Real Decreto 640/2007, no será obligatorio el cumplimiento de las obligaciones impuestas en la normativa europea, en relación con la instalación y uso del tacógrafo y los tiempos de conducción y descanso de los conductores, durante la realización de:",o:{a:"Transportes de carácter privado complementario relacionados con el circo y atracciones de feria.",b:"Transportes de exposiciones móviles de fondos u objetos de valor.",c:"Transportes realizados mediante vehículos propulsados por electricidad o gas, cuya MMA no supere las 7,5 Tm, siempre que se desarrollen dentro de un radio de 100 km, y la conducción de vehículos no constituya la actividad principal del conductor.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Circo y atracciones de feria (a), exposiciones móviles de valor (b) y vehículos eléctricos/gas de hasta 7,5 Tm en 100 km (c) están exentos según el art.2 del RD 640/2007."}},
{n:96,q:"De acuerdo con lo dispuesto en el Real Decreto 640/2007, están excluidos de la instalación y uso del tacógrafo...",o:{a:"Los transportes oficiales y de empresas dedicadas a la importación de productos energéticos e informáticos.",b:"Los transportes que se utilicen por el servicio postal, siempre y cuando no superen las 3,5 Tm y se realicen en un radio de 50 Km alrededor del centro empresarial; y siempre que la conducción no constituya la actividad principal del conductor.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{d:"La opción b) es incorrecta (el límite del servicio postal es 7,5 Tm, no 3,5 Tm) y la opción a) tampoco es correcta tal como está formulada; por tanto ambas son incorrectas."}},
{n:97,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"El tiempo diario de conducción no será superior a nueve horas.",b:"El tiempo diario de conducción podrá ampliarse como máximo hasta 10 horas no más de tres veces durante la semana.",c:"El tiempo de conducción semanal no superará las 46 horas y no implicará que se exceda el tiempo semanal de trabajo máximo, fijado en la Directiva 2002/15/CE.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El tiempo diario de conducción no será superior a nueve horas, aunque puede ampliarse hasta 10 horas dos veces por semana (no tres). La opción a) es la única correcta."}},
{n:98,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"El tiempo diario de conducción podrá ampliarse como máximo hasta 11 horas no más de dos veces durante la semana.",b:"El tiempo de conducción semanal no superará las 56 horas y no implicará que se exceda el tiempo semanal de trabajo máximo, fijado en la Directiva 2002/15/CE.",c:"El tiempo total acumulado de conducción durante dos semanas consecutivas no será superior a 95 horas.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"El tiempo de conducción semanal no superará las 56 horas y no excederá el tiempo máximo semanal de trabajo establecido en la Directiva 2002/15/CE."}},
{n:99,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"Tras un período de conducción de cuatro horas y media, el conductor hará una pausa ininterrumpida de al menos 45 minutos, a menos que tome un período de descanso.",b:"Podrá sustituirse dicha pausa por una pausa de al menos 15 minutos seguida de una pausa de al menos 30 minutos, intercaladas en el período de conducción.",c:"Los conductores deberán tomar períodos de descanso diarios y semanales.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones son correctas: pausa de 45 min tras 4,5 h de conducción (a), posibilidad de dividirla en 15+30 min (b) y obligación de descansos diarios y semanales (c)."}},
{n:100,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"Los conductores deberán haberse tomado un nuevo período de descanso diario en las 12 horas siguientes al final de su período de descanso diario o semanal anterior.",b:"Si la parte del período de descanso diario efectuada en las mencionadas 12 horas es superior a 9 horas, pero inferior a 11, ese período de descanso se considerará un período de descanso diario reducido.",c:"Un período de descanso diario podrá ampliarse para transformarse en un período de descanso semanal normal o reducido.",d:"Todas las respuestas anteriores son correctas."},correct:"c",why:{c:"Un período de descanso diario podrá ampliarse para transformarse en un período de descanso semanal normal o reducido, lo cual es correcto; las opciones a) y b) contienen cifras incorrectas."}},
{n:101,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"Los conductores no podrán tomarse más de dos períodos de descanso diario reducidos entre dos períodos de descanso semanales.",b:"En el transcurso de dos semanas consecutivas el conductor tendrá que tomar al menos dos períodos de descanso semanal normales, o un período de descanso semanal normal y un período de descanso semanal reducido de al menos 24 horas.",c:"El período de descanso semanal comenzará antes de que hayan concluido tres períodos consecutivos de 24 horas desde el final del anterior período de descanso semanal.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"En dos semanas consecutivas el conductor tomará al menos dos descansos semanales normales, o uno normal y uno reducido de al menos 24 horas; esta es la única opción correcta de las tres."}},
{n:102,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"Se considera pausa cualquier período durante el cual un conductor no pueda llevar a cabo ninguna actividad de conducción u otro trabajo, la utilice o no para su reposo.",b:"Se considera período de descanso diario el período diario durante el cual un conductor puede disponer libremente de su tiempo, ya sea un período de descanso diario normal o un período de descanso diario reducido.",c:"Se considera período de descanso diario normal, cualquier período de descanso de al menos 11 horas. Alternativamente, el período de descanso diario normal se podrá tomar en dos períodos, el primero de ellos de al menos 4 horas ininterrumpidas y el segundo de al menos 8 horas ininterrumpidas.",d:"Se considera período de descanso diario reducido, cualquier período de descanso de al menos 8 horas, pero inferior a 11 horas."},correct:"b",why:{b:"El período de descanso diario es aquel en que el conductor puede disponer libremente de su tiempo (normal o reducido); la pausa (a) es distinta, y el descanso reducido mínimo es de 9 horas, no 8 (d)."}},
{n:103,q:"En materia de transporte, y de acuerdo con lo dispuesto en el Reglamento CE 561/2006...",o:{a:"Se considera período de descanso semanal, el período semanal durante el cual un conductor puede disponer libremente de su tiempo, siempre que se trate de un periodo de descanso semanal normal.",b:"Se considera período de descanso semanal normal cualquier período de descanso de al menos 45 horas.",c:"Se considera período de descanso semanal reducido cualquier período de descanso inferior a 40 horas que, sujeto a las condiciones establecidas en el artículo 8.6, se puede reducir hasta un mínimo de 12 horas consecutivas.",d:"Se considera semana el período de tiempo comprendido entre las 01.00 del lunes y las 24.00 del domingo;"},correct:"b",why:{b:"El período de descanso semanal normal es cualquier período de descanso de al menos 45 horas. Las demás opciones contienen datos incorrectos."}},
{n:104,q:"Respecto a los tiempos de conducción y de conformidad con lo establecido en la legislación de transportes, existe la posibilidad de un descanso semanal reducido, con un mínimo de 24 horas consecutivas.",o:{a:"Correcto, siempre que se cumplan las condiciones establecidas en el artículo 8.6 del Reglamento 561/2006 del Parlamento Europeo y del Consejo.",b:"Incorrecto. En ningún caso pueden modificarse los tiempos mínimos de conducción semanal.",c:"Correcto, siempre que se cumplan las condiciones establecidas en el artículo 6.2 de la Ley 16/1987.",d:"Correcto, salvo en determinados tipos de transporte."},correct:"a",why:{a:"Es correcto que existe la posibilidad de descanso semanal reducido con mínimo de 24 horas, siempre que se cumplan las condiciones del art.8.6 del Reglamento CE 561/2006."}},
{n:105,q:"De conformidad con la legislación de transportes, el tiempo total acumulado de conducción durante dos semanas consecutivas no será superior a:",o:{a:"90 horas.",b:"80 horas.",c:"70 horas.",d:"El establecido con carácter general en el Estatuto de los trabajadores."},correct:"a",why:{a:"El tiempo total acumulado de conducción en dos semanas consecutivas no puede superar las 90 horas, conforme al Reglamento CE 561/2006."}},
{n:106,q:"Para realizar transportes públicos discrecionales:",o:{a:"Se precisa autorización administrativa.",b:"Es necesario haber obtenido una concesión administrativa.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Para realizar transportes públicos discrecionales se precisa autorización administrativa, no concesión; la concesión es propia de los servicios regulares."}},
{n:107,q:"Según el artículo 91 de la Ley de Ordenación de Transportes Terrestres...",o:{a:"Las autorizaciones de transporte privado habilitarán para realizar servicios en todo el territorio nacional sin limitación alguna por razón del origen o destino del servicio.",b:"Las autorizaciones de transporte de viajeros en vehículos de turismo y las de arrendamiento de vehículos con conductor habilitarán exclusivamente para realizar transporte interurbano de viajeros.",c:"En todo caso, los servicios de arrendamiento de vehículos con conductor deberán iniciarse en el territorio de la comunidad autónoma en que se encuentre domiciliada la correspondiente autorización.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Las autorizaciones de transporte de viajeros en turismo y de arrendamiento con conductor habilitan exclusivamente para el transporte interurbano de viajeros, conforme al art.91 de la Ley 16/1987."}},
{n:108,q:"Según el artículo 98 de la Ley de Ordenación de Transportes Terrestres...",o:{a:"La autorización de transporte público de mercancías habilita para realizar transportes de esta clase, en las condiciones señaladas en el artículo 64 de esta Ley.",b:"Durante la realización de transportes de mercancías, únicamente podrán ocupar el vehículo personas distintas a su conductor y tripulación cuando así lo posibilite el correspondiente permiso de circulación y su transporte no dé lugar a retribución alguna a favor del transportista.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Durante el transporte de mercancías, el vehículo solo puede ser ocupado por personas distintas al conductor cuando el permiso de circulación lo permita y su transporte no suponga retribución alguna al transportista."}},
{n:109,q:"En el ámbito de los servicios de transporte de carácter discrecional, en supuestos especiales, la Administración podrá establecer un régimen de servicios mínimos de carácter obligatorio.",o:{a:"No es cierto. Esta práctica está prohibida.",b:"Correcto. Así lo dispone el art.94 de la Ley 16/1987 de Ordenación de los Transportes Terrestres.",c:"Correcto, debiendo ajustarse a lo establecido en el art.8.6 de la CE 361/2006 del Parlamento Europeo y del Consejo.",d:"Correcto, debiendo ajustarse a lo establecido en el art.8.6 de la Ley 16/1987 de ordenación de los Transportes Terrestres."},correct:"b",why:{b:"Es correcto; el art.94 de la Ley 16/1987 permite a la Administración establecer servicios mínimos obligatorios en el ámbito del transporte discrecional en supuestos especiales."}},
{n:110,q:"Los vehículos amparados por una autorización de transporte discrecional de viajeros, podrán transportar objetos o encargos distintos de los equipajes de los viajeros:",o:{a:"Cuando ello resulte compatible con las características del vehículo.",b:"Cuando ello no implique molestias para los viajeros.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Los vehículos de transporte discrecional pueden transportar objetos distintos a los equipajes cuando ello sea compatible con las características del vehículo (a) y no implique molestias para los viajeros (b)."}},
{n:111,q:"La Ley del Taxi en la Comunitat Valenciana es la:",o:{a:"Ley 13/2017.",b:"Ley 17/2013.",c:"Ley 13/2014.",d:"Ley 17/2014"},correct:"a",why:{a:"La Ley del Taxi en la Comunitat Valenciana es la Ley 13/2017, que regula el servicio de taxi en dicho ámbito territorial."}},
{n:112,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, se entiende por servicio de taxi el transporte público discrecional de viajeros realizado:",o:{a:"En vehículos turismo y disponiendo del correspondiente título habilitante.",b:"Por cuenta ajena.",c:"Mediante retribución económica sujeta a tarifa y mediante contrato por la capacidad total del vehículo.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El servicio de taxi implica todas las características indicadas: vehículo turismo con título habilitante (a), por cuenta ajena (b) y con retribución sujeta a tarifa por la capacidad total (c)."}},
{n:113,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta correcta:",o:{a:"Los municipios que no formen parte de un área de prestación conjunta, son competentes sobre los servicios de transporte urbano en taxi que se presten íntegramente dentro de su municipio.",b:"Las competencias de la Generalitat sobre transporte interurbano en taxi prestado entre municipios o áreas de prestación conjunta de la Comunitat Valenciana, se ejercerán conciliando la normativa de aplicación con la que hubiera vigente para los transportes interurbanos de ámbito nacional.",c:"La conselleria competente en materia de transporte tiene competencia para la gestión, ordenación y control de los servicios de transporte urbano en taxi prestados dentro de un ámbito supramunicipal configurado como área de prestación conjunta de la Comunitat Valenciana.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones sobre la distribución competencial del taxi en la Comunitat Valenciana son correctas conforme a la Ley 13/2017."}},
{n:114,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta que no es correcta:",o:{a:"El servicio de taxi se realizará previa autorización administrativa expedida por la conselleria que tenga atribuidas las competencias en materia de transportes, o por los ayuntamientos cuyos municipios no se hayan integrado en un área de prestación conjunta para la prestación del servicio de taxi.",b:"La autorización para el servicio de taxi será otorgada por tiempo máximo de 5 años.",c:"La autorización para el servicio de taxi se otorgará en favor de personas físicas habilitadas al efecto y que solo podrán ser titulares de una única autorización y para un vehículo.",d:"La autorización para el servicio de taxi habilitará para la prestación de servicios dentro del ámbito municipal o del de un área supramunicipal en caso de que se haya creado un área de prestación conjunta para los servicios de taxi que integre a varios municipios."},correct:"b",why:{b:"La opción b) es incorrecta: las autorizaciones de taxi no se otorgan por un plazo máximo de 5 años, sino de forma indefinida, condicionando su validez al visado periódico."}},
{n:115,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y en lo que respecta a las autorizaciones para el servicio de taxi, indique la respuesta que no es correcta:",o:{a:"La autorización habilitará para recoger a personas usuarias en poblaciones de otros ámbitos limítrofes o próximos cuando el servicio se solicite desde un municipio que no disponga de autorizaciones.",b:"La autorización habrá de vincularse, y será previa, a la expedición de la autorización de transporte interurbano competencia del Estado, a fin de que el taxi quede habilitado, asimismo, para la prestación de servicios que excedan del territorio de su correspondiente ámbito funcional.",c:"El otorgamiento de nuevas autorizaciones de taxi se realizará a través de procedimientos de libre concurrencia.",d:"A las nuevas autorizaciones de taxi se adscribirá un vehículo de hasta cinco años de antigüedad."},correct:"d",why:{d:"La opción d) es incorrecta: las nuevas autorizaciones de taxi tienen adscrito un vehículo de hasta dos años de antigüedad, no cinco."}},
{n:116,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, el titular de una autorización de taxi...",o:{a:"Debe tener nacionalidad española o de un Estado miembro de la Unión Europea o de otro país extranjero en el que, en virtud de acuerdos, tratados o convenios internacionales suscritos por España, contemple la reciprocidad.",b:"Debe haber superado pruebas acreditativas de su capacitación profesional para la prestación del servicio convocadas por la conselleria o ayuntamiento correspondiente.",c:"Debe tener la autorización para conducir prevista por la normativa de circulación, tráfico y seguridad vial para conducir vehículos de turismo con antigüedad mínima de un año.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres condiciones son exigibles al titular de una autorización de taxi según la Ley 13/2017: nacionalidad o reciprocidad (a), pruebas de capacitación (b) y permiso de conducir turismo con un año de antigüedad mínima (c)."}},
{n:117,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, el titular de una autorización de taxi...",o:{a:"Debe cumplir el requisito de honorabilidad, en los términos establecidos en la legislación estatal y europea para el ejercicio de la profesión de transportista por carretera.",b:"Debe carecer de antecedentes penales por delitos relacionados con la seguridad vial, la integridad de las personas, por delitos de violencia de género o delitos de odio, siempre que las penas impuestas por estos delitos sean superiores a 3 años.",c:"Debe acreditar el cumplimiento de las obligaciones familiares, morales, fiscales, sociales, laborales y medioambientales exigidas por la normativa al efecto.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El titular debe cumplir el requisito de honorabilidad en los términos de la legislación estatal y europea para el ejercicio de la profesión de transportista por carretera."}},
{n:118,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, el titular de una autorización de taxi...",o:{a:"Debe acreditar la titularidad de un vehículo de turismo que cumpla las condiciones establecidas para los mismos en régimen de propiedad, arrendamiento financiero, renting u otro régimen admitido por la normativa vigente que atribuya la plena disponibilidad del vehículo, domiciliado en el ámbito en el que se le otorgue la autorización o en un municipio próximo y accesible",b:"Debe tener cubierta la responsabilidad civil por los daños que pudieran ocasionarse en la prestación del servicio, según lo dispuesto en la normativa vigente.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas son exigidas por la Ley 13/2017: acreditar titularidad del vehículo en el ámbito de la autorización (a) y tener cubierta la responsabilidad civil (b)."}},
{n:119,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta que no es correcta.",o:{a:"Los titulares de autorizaciones de taxi en municipios o áreas de 200.000 habitantes o más, explotarán su taxi con plena y exclusiva dedicación.",b:"Las autorizaciones del taxi se expiden de forma indefinida, si bien su validez quedará condicionada a su visado periódico.",c:"Se podrá solicitar la suspensión de la autorización de servicio de taxi por un plazo de tres años, prorrogables otros dos años, si se acreditaran causas justificadas de carácter personal que impidieran ejercer la actividad.",d:"En áreas o municipios de más de 50.000 habitantes, la suspensión de la autorización de servicio de taxi podrá serlo por un plazo de tres años, prorrogables otros tres años, si se acreditaran causas justificadas de carácter personal que impidieran ejercer la actividad."},correct:"c",why:{c:"La opción c) es incorrecta: la suspensión puede solicitarse por un plazo de tres años, prorrogables otros tres años (no dos) si se acreditan causas justificadas de carácter personal."}},
{n:120,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta que no es correcta.",o:{a:"La validez de las autorizaciones de taxi quedará condicionada a su visado periódico cada cuatro años.",b:"Transcurrido el plazo previsto para la realización del visado sin haberlo efectuado, si se acredita el cumplimiento de las condiciones establecidas, se podrá acceder a su rehabilitación durante los seis meses inmediatamente siguientes a la finalización de dicho plazo.",c:"Podrá procederse, excepcionalmente, a la reactivación de la autorización, dentro de los cuatro años siguientes, si se acreditara la concurrencia de causas justificadas de carácter personal de su titular que hubieran impedido el visado o la rehabilitación, siempre que se cumplan todos los requisitos exigidos para las nuevas autorizaciones.",d:"El objeto del visado es comprobar que se mantienen las condiciones en que la autorización fue expedida y que se continúan cumpliendo las obligaciones de carácter fiscal, social, laboral, técnico y medioambiental y de antigüedad e idoneidad del vehículo y, en su caso, de su taxímetro, así como las condiciones de dedicación de su titular y su obligación de prestar habitualmente el servicio."},correct:"b",why:{b:"La opción b) es incorrecta: la rehabilitación puede solicitarse durante el mes siguiente a la finalización del plazo del visado, no durante seis meses."}},
{n:121,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta que no es correcta.",o:{a:"Las autorizaciones de taxi de nueva creación no podrán transmitirse durante los cuatro años siguientes a su adjudicación, salvo en supuestos del fallecimiento de su titular o de declaración de jubilación o incapacidad.",b:"Cuando la transmisión sea de una autorización de taxi que tiene vehículo adaptado adscrito, el nuevo titular, en todo caso, deberá adscribir a la autorización otro vehículo adaptado.",c:"Las autorizaciones de taxi podrán transmitirse por sus titulares, o personas herederas, en favor de una persona física que cumpla los requisitos establecidos para ser titular de autorización de taxi.",d:"Se establece el plazo de dos años para la transmisión de las autorizaciones de taxi a favor de las personas herederas en caso de fallecimiento del titular de la autorización."},correct:"a",why:{a:"La opción a) es incorrecta: las autorizaciones de nueva creación no pueden transmitirse en los primeros dos años (no cuatro) salvo fallecimiento, jubilación o incapacidad."}},
{n:122,q:"De acuerdo con lo previsto en la Ley 13/2017, las autorizaciones para servicio de taxi se extinguen...",o:{a:"En caso de renuncia por parte de su titular.",b:"Por caducidad.",c:"Por revocación.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las autorizaciones de taxi se extinguen por renuncia del titular (a), por caducidad (b) y por revocación (c); las tres causas son válidas según la Ley 13/2017."}},
{n:123,q:"De acuerdo con lo previsto en la Ley 13/2017, la extinción de la autorización para servicio de taxi se extingue por caducidad cuando...",o:{a:"Se produce la renuncia por parte de su titular.",b:"No se solicita el reinicio de la actividad, antes de finalizar el plazo de suspensión concedido.",c:"El vehículo excede de la antigüedad máxima establecida.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"La autorización se extingue por caducidad cuando, concluido el plazo de suspensión, no se solicita el reinicio de la actividad. La renuncia da lugar a extinción por renuncia, y exceder la antigüedad del vehículo da lugar a revocación."}},
{n:124,q:"De acuerdo con lo previsto en la Ley 13/2017, la extinción de la autorización para servicio de taxi se extingue por revocación cuando...",o:{a:"El vehículo excede de la antigüedad máxima establecida.",b:"Se produce un incumplimiento de los plazos de visado y rehabilitación y no concurren las causas para su reactivación alegadas por su titular.",c:"Se produce la renuncia por parte de su titular.",d:"No se solicita el reinicio de la actividad, antes de finalizar el plazo de suspensión concedido."},correct:"a",why:{a:"La autorización se revoca cuando el vehículo excede la antigüedad máxima establecida; el incumplimiento de plazos de visado también genera revocación en determinadas circunstancias."}},
{n:125,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta correcta.",o:{a:"Con carácter general, el transporte público de taxi se realizará con vehículos de entre cinco y siete plazas incluido el conductor, si bien podrá ser ampliable hasta nueve plazas en supuestos excepcionales.",b:"Tanto en municipios como en áreas de prestación conjunta, situados en zonas rurales del interior, podrán autorizarse vehículos de hasta nueve plazas, siempre que concurran razones de interés público para ello.",c:"Se autorizarán vehículos de hasta nueve plazas, incluido conductor, y plaza o plazas adaptadas, en un municipio o área de prestación conjunta.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones sobre los vehículos de taxi en la Comunitat Valenciana son correctas conforme a la Ley 13/2017."}},
{n:126,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y en relación con los vehículos que presten este servicio, indique la respuesta que no es correcta.",o:{a:"Deberán ir identificados por su matrícula, además de incorporar los distintivos de taxi de forma permanente, tanto en puertas laterales como en la parte trasera.",b:"Dispondrán de módulo exterior que indique su disponibilidad o no para prestar servicio y, en su caso, la tarifa que se esté aplicando cuando se realiza el servicio.",c:"Si se trata de un municipio o área de prestación conjunta de una población de 30.000 habitantes o superior, o que tenga autorizada una tarifa urbana, el vehículo deberá tener instalado el correspondiente aparato medidor de las tarifas, con su correspondiente módulo que identifique todas las tarifas.",d:"Los vehículos serán conducidos por personas físicas titulares de los mismos o, previa comunicación a la administración competente en materia de transportes, por conductores asalariados o familiares colaboradores."},correct:"c",why:{c:"La opción c) es incorrecta: el umbral de población para el taxímetro obligatorio es de 50.000 habitantes (no 30.000), o cuando tenga autorizada una tarifa urbana."}},
{n:127,q:"De acuerdo con lo previsto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y en relación con los vehículos que presten este servicio, indique la respuesta que no es correcta.",o:{a:"Los vehículos adaptados darán servicio a las personas con movilidad reducida con carácter exclusivo.",b:"Con carácter general, los vehículos tendrán una longitud mínima exterior, medida de extremo a extremo, igual o superior a 4,60 metros.",c:"La antigüedad de los vehículos de turismo que presten servicio de taxi no excederá, con carácter general, de doce años, contados desde su primera matriculación, u otra inferior que pueda establecer la Consellería o el ayuntamiento competente.",d:"En áreas o municipios de 200.000 habitantes o con más de 200 taxis, la antigüedad máxima será de 10 años, o de 12 años para vehículos eléctricos o híbridos."},correct:"a",why:{a:"La opción a) es incorrecta: los vehículos adaptados no tienen carácter exclusivo para PMR; también pueden prestar servicio a cualquier usuario cuando no haya demanda específica."}},
{n:128,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, los usuarios tienen derecho...",o:{a:"A transportar un animal doméstico, siempre que con ello no se comprometa la seguridad.",b:"A que no se fume en el interior del vehículo.",c:"A consumir cualquier bebida no alcohólica siempre que con ello no se ensucie ni deteriore el vehículo.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Los usuarios tienen derecho a que no se fume en el interior del vehículo de taxi, conforme a la Ley 13/2017. El transporte de animales domésticos y el consumo de bebidas son objeto de regulación adicional."}},
{n:129,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, los usuarios tienen derecho...",o:{a:"A que no se le ofrezca publicidad sin previo y expreso consentimiento.",b:"A que se modere el sonido de radio o similar",c:"Al transporte gratuito de equipaje aunque con los límites de peso y volumen propios de las características del vehículo, pudiendo utilizar las plazas no ocupadas por los usuarios, garantizando las condiciones de seguridad necesarias.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres son derechos del usuario del taxi: no recibir publicidad sin consentimiento (a), que se modere el sonido (b) y el transporte gratuito de equipaje (c)."}},
{n:130,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, los usuarios tienen derecho...",o:{a:"A acceder al servicio de taxi, en las paradas establecidas al efecto, por orden de prioridad con respecto a otros usuarios.",b:"A que se facilite a la persona usuaria la posibilidad de pago por medios telemáticos.",c:"A subir y bajar del vehículo cuando lo considere oportuno.",d:"Todas las respuestas anteriores son correctas."},correct:"b",why:{b:"Los usuarios tienen derecho a que se les facilite el pago por medios telemáticos, conforme a la Ley 13/2017. El acceso es por orden de llegada (no prioridad) y el conductor decide las paradas seguras."}},
{n:131,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, los usuarios tienen el deber...",o:{a:"Pagar el precio de la prestación del servicio de acuerdo con el régimen de tarifas establecido.",b:"No manipular, destruir o deteriorar ningún elemento del vehículo durante el servicio.",c:"Acceder al servicio de taxi, en las paradas establecidas al efecto, por orden de llegada a las mismas y al primer vehículo ordenado en disposición de prestar adecuadamente el servicio a las necesidades de las personas usuarias.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Los tres son deberes de los usuarios del taxi: pagar la tarifa (a), no dañar el vehículo (b) y acceder por orden de llegada en las paradas (c)."}},
{n:132,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y con relación a las obligaciones que tienen los prestadores del servicio de taxi, indique la respuesta que no es correcta.",o:{a:"Cuidar las buenas formas en relación con los agentes de la autoridad y personal funcionario con el que se relacionen.",b:"Adoptar elementos de uniformidad en la vestimenta, si así lo estableciera el ayuntamiento o la conselleria competente.",c:"Mantener de forma permanente un aseo personal adecuado así como una vestimenta adecuada a la atención al público y que aseguren una conducción segura.",d:"Respetar las normas que se establezcan sobre tiempos máximos de conducción y de descanso obligatorio."},correct:"a",why:{a:"La opción a) es incorrecta: cuidar las buenas formas con los agentes de la autoridad no es una obligación del prestador del taxi; sí lo son la uniformidad (b), el aseo personal (c) y el respeto a los tiempos de conducción (d)."}},
{n:133,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y con relación a las obligaciones que tienen los prestadores del servicio de taxi, indique la respuesta que no es correcta.",o:{a:"Prohibición de consumir alimentos y bebidas, salvo las hidratantes, durante la prestación del servicio.",b:"Ofrecer la resolución de los conflictos a través del órgano jurisdiccional correspondiente.",c:"Custodiar, hasta la entrega a la autoridad competente, los objetos perdidos o abandonados en el vehículo.",d:"Prestar los servicios de taxi con vehículos que no excedan de la antigüedad máxima establecida, aun teniendo autorización vigente."},correct:"b",why:{b:"La opción b) es incorrecta: la resolución de conflictos en el taxi se realiza a través del órgano arbitral o de mediación, no necesariamente del órgano jurisdiccional."}},
{n:134,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y con relación a las obligaciones que tienen los prestadores del servicio de taxi, indique la respuesta que no es correcta.",o:{a:"Utilizar las preceptivas señales luminosas de indicación de la situación de libre u ocupado y de la tarifa que se está aplicando.",b:"Conocer, en todo caso, el destino del servicio solicitado, si su identificación es la postal.",c:"Descontar a la persona usuaria, en los servicios recabados telefónica o telemáticamente, la cantidad de exceso que marque el taxímetro, en el momento en que el vehículo llegue al punto y hora acordados, respecto al máximo que pudiera haberse establecido al efecto.",d:"Manipular el taxímetro durante la prestación del servicio en concordancia con el régimen tarifario establecido, salvo que esté previsto el cambio de tarifa por paso de zona, y salvo la tarifa de retorno para servicios interurbanos."},correct:"d",why:{d:"La opción d) es incorrecta: la manipulación del taxímetro durante el servicio está prohibida; lo que corresponde es ajustarlo al régimen tarifario sin manipulación, salvo los supuestos legalmente previstos."}},
{n:135,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y con relación a las obligaciones que tienen los prestadores del servicio de taxi, indique la respuesta que no es correcta.",o:{a:"Percibir el importe que marque el taxímetro o, en su caso, el mínimo de percepción establecido o el importe convenido por un servicio interurbano, si resultara inferior al resultante por aplicación de la tarifa.",b:"Evitar cualquier tipo de discriminación en el acceso a la prestación del servicio de taxi, no pudiéndose negar a prestar el servicio, salvo causas justificadas establecidas en esta ley o en una normativa al efecto.",c:"No insertar en el vehículo ningún tipo de publicidad sexista o de otro orden que atente contra la dignidad de la persona o vulnere los valores o derechos reconocidos en la Constitución, así como aquella relacionada con la prostitución o con la ocupación ilegal.",d:"Mantener visible, desde el exterior del vehículo, y sin interferencias en su entorno, el número de autorización y el distintivo del municipio o área, el módulo luminoso identificativo de las tarifas y el indicativo de disponible u ocupado."},correct:"c",why:{c:"La opción c) es incorrecta: la prohibición de publicidad sexista o atentatoria contra la dignidad no es una obligación del prestador, sino más bien una restricción; las opciones a), b) y d) sí son obligaciones expresas."}},
{n:136,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, y con relación a las obligaciones que tienen los prestadores del servicio de taxi, indique la respuesta correcta.",o:{a:"Suministrar, a petición del usuario del taxi, el modelo oficial de hojas de reclamaciones e informarle de los trámites necesarios para su cumplimentación.",b:"Garantizar la visibilidad, desde el interior del vehículo, del documento de identificación del conductor que será de color naranja, del número de autorización y de las tarifas.",c:"Proporcionar un justificante del precio abonado por el servicio, y justificarse ante la persona usuaria en caso de que, hubiera de exigirse el pago por anticipado.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres son obligaciones correctas del prestador del taxi: facilitar hojas de reclamaciones (a), garantizar la visibilidad de la identificación del conductor (b) y proporcionar justificante del precio (c)."}},
{n:137,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique cuál de las siguientes infracciones tiene la consideración de grave.",o:{a:"No llevar en lugar visible los distintivos, rótulos, avisos o cualquier otro documento que fueran exigibles.",b:"Prestar el servicio de transporte público discrecional de viajeros en vehículos de turismo sin la autorización preceptiva.",c:"Carecer del preceptivo documento en el que deben formularse las reclamaciones de las personas usuarias o negar u obstaculizar su disposición al público.",d:"No entregar el recibo o factura del servicio prestado a las personas usuarias, si estas lo solicitasen."},correct:"c",why:{c:"Carecer del libro o documento de reclamaciones o impedir su acceso al público es una infracción grave conforme a la Ley 13/2017. Las opciones a), b) y d) tienen distinta graduación."}},
{n:138,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique cuál de las siguientes infracciones tiene la consideración de grave.",o:{a:"No atender la solicitud a una demanda de servicio de taxi por parte de una persona usuaria estando de servicio.",b:"La prestación de servicios en condiciones que puedan afectar a la seguridad de las personas.",c:"Prestar el servicio con un número de ocupantes del vehículo que supere el número de plazas autorizadas, de conformidad con la normativa vigente",d:"La carencia de cambio de moneda metálica o billetes hasta la cantidad que esté reglamentariamente establecida"},correct:"a",why:{a:"No atender una demanda de servicio estando de servicio es una infracción grave conforme a la Ley 13/2017 del Taxi de la Comunitat Valenciana."}},
{n:139,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique cuál de las siguientes infracciones tiene la consideración de grave.",o:{a:"No llevar el aparato taxímetro en caso de que este fuera exigible.",b:"La negativa u obstrucción a la actuación de los servicios de inspección o de las fuerzas encargadas de la vigilancia del transporte que imposibiliten total o parcialmente el ejercicio de las funciones que legal o reglamentariamente tengan atribuidas.",c:"La realización de servicios de taxi por itinerarios inadecuados que fueran lesivos económicamente para los intereses de la persona usuaria o desatendiendo sus indicaciones.",d:"No exponer al público los cuadros de tarifas autorizados o tenerlos en lugares no visibles."},correct:"c",why:{c:"La realización de servicios por itinerarios inadecuados que perjudiquen económicamente al usuario o contravengan sus indicaciones es infracción grave según la Ley 13/2017."}},
{n:140,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique cuál de las siguientes infracciones tiene la consideración de grave.",o:{a:"El cobro por pasajero en lugar de por coche completo, salvo en los supuestos en que estuviese expresamente autorizado.",b:"La alteración o inadecuada utilización de los distintivos o señalizaciones que fueran exigibles para la prestación del servicio de taxi.",c:"La difusión de ofertas comerciales para la realización de actividades de transporte de personas en vehículos de turismo sin disponer de los correspondientes títulos habilitantes para ejercer dichas actividades.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres conductas son infracciones graves conforme a la Ley 13/2017: cobro por pasajero en lugar de por vehículo (a), alteración de distintivos (b) y difusión de ofertas sin título habilitante (c)."}},
{n:141,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique cuál de las siguientes infracciones tiene la consideración de grave.",o:{a:"El trato desconsiderado o vejatorio a las personas usuarias del taxi",b:"El descuido en el aseo personal o falta de limpieza en el interior o exterior del vehículo.",c:"Abandonar un servicio antes de su finalización, salvo que existiesen causas justificadas de peligro fundado para la persona conductora o para el vehículo de turismo.",d:"Todas las respuestas anteriores son correctas."},correct:"c",why:{c:"Abandonar un servicio antes de su finalización sin causa justificada es infracción grave. El trato desconsiderado (a) o el descuido en el aseo (b) tienen distinta graduación."}},
{n:142,q:"De conformidad con lo dispuesto en la Ley 13/2017, del Taxi en la Comunitat Valenciana, indique la respuesta correcta.",o:{a:"Las infracciones leves se sancionarán con multas de hasta 600 euros.",b:"Las infracciones graves se sancionarán con multa desde 601 hasta 2.000 euros.",c:"Las infracciones muy graves se sancionarán con multa desde 2.001 hasta 6.000 euros.",d:"Todas las respuestas anteriores son correctas."},correct:"c",why:{c:"Las infracciones muy graves en materia de taxi se sancionan con multa de entre 2.001 y 6.000 euros conforme a la Ley 13/2017."}},
{n:143,q:"Los vehículos destinados al arrendamiento de vehículos con conductor deben tener una capacidad que no supere...",o:{a:"Nueve plazas, incluido el conductor,",b:"Ocho plazas, incluido el conductor,",c:"Siete plazas, incluido el conductor,",d:"Cinco plazas, incluido el conductor,"},correct:"a",why:{a:"Los vehículos de arrendamiento con conductor (VTC) deben tener una capacidad máxima de nueve plazas, incluido el conductor."}},
{n:144,q:"El motor de los vehículos dedicados a la actividad de arrendamiento con conductor, tendrá una potencia:",o:{a:"Igual o superior a 12 caballos de vapor fiscales (CVF).",b:"Igual o superior a 18 caballos de vapor fiscales (CVF).",c:"Mínima de 14 caballos de vapor fiscales (CVF).",d:"Mínima de 18 caballos de vapor fiscales (CVF)."},correct:"a",why:{a:"Los vehículos VTC deben tener un motor con potencia igual o superior a 12 caballos de vapor fiscales (CVF)."}},
{n:145,q:"Los vehículos dedicados a la actividad de arrendamiento con conductor tendrán una longitud mínima exterior:",o:{a:"Igual o superior a 5,60 metros, medida de extremo a extremo del vehículo.",b:"Igual o superior a 4,60 metros, medida de extremo a extremo del vehículo.",c:"Igual o superior a 4,80 metros, medida de extremo a extremo del vehículo.",d:"Igual o superior a 3,80 metros, medida de extremo a extremo del vehículo."},correct:"b",why:{b:"Los vehículos VTC deben tener una longitud mínima exterior de 4,60 metros, medida de extremo a extremo."}},
{n:146,q:"Los vehículos dedicados a la actividad de arrendamiento con conductor no podrán continuar ejerciendo dicha actividad:",o:{a:"A partir del momento en que alcancen los 10 años de antigüedad.",b:"A partir del momento en que alcancen los 12 años de antigüedad.",c:"A partir de los 12 años de antigüedad.",d:"A partir de los 14 años de antigüedad."},correct:"a",why:{a:"Los vehículos VTC no pueden continuar ejerciendo la actividad a partir de que alcancen los 10 años de antigüedad."}},
{n:147,q:"La antigüedad máxima de 10 años, impuesta a los vehículos dedicados a la actividad de arrendamiento con conductor, no será aplicable:",o:{a:"Cuando se trate de vehículos con potencia superior a 28 CVF.",b:"Cuando se trate de vehículos históricos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El límite de 10 años de antigüedad no se aplica a los vehículos con potencia superior a 28 CVF (a) ni a los vehículos históricos (b), siendo correctas ambas excepciones."}},
{n:148,q:"Respecto a los vehículos dedicados a la actividad de arrendamiento con conductor, señale la afirmación incorrecta:",o:{a:"Cuando vayan ocupados por personas ajenas a la empresa titular de la autorización, únicamente podrán circular si se justifica que están prestando un servicio previamente contratado y el contrato que lo justifica está a bordo del vehículo.",b:"No podrán continuar ejerciendo dicha actividad a partir de que alcancen los 12 años de antigüedad.",c:"Este tipo de arrendamiento se considera transporte discrecional de viajeros.",d:"Ninguna de las anteriores afirmaciones es incorrecta."},correct:"b",why:{b:"La opción b) es incorrecta: el límite de antigüedad de los vehículos VTC es de 10 años, no de 12. Las opciones a) y c) son afirmaciones correctas."}},
{n:149,q:"Respecto a la actividad de arrendamiento de vehículos con conductor, la habilitación del Estado a las CCAA para otorgar autorizaciones se produjo por medio del...",o:{a:"Real Decreto 21/2018.",b:"Real Decreto 12/2018.",c:"Real Decreto 31/2018.",d:"Real Decreto 13/2018."},correct:"d",why:{d:"La habilitación del Estado a las Comunidades Autónomas para otorgar autorizaciones VTC se produjo mediante el Real Decreto 13/2018."}},
{n:150,q:"El régimen de arrendamiento de vehículos con conductor (VTC) en el ámbito de la Comunitat Valenciana, se regula en...",o:{a:"Decreto Ley 2/2019.",b:"Decreto 2/2019.",c:"Decreto Ley 4/2019.",d:"Decreto 4/2019."},correct:"c",why:{c:"El régimen de arrendamiento de vehículos con conductor (VTC) en la Comunitat Valenciana se regula en el Decreto Ley 4/2019."}},
{n:151,q:"El control de la explotación de las autorizaciones de arrendamiento de vehículos con conductor (VTC) se regula en el...",o:{a:"Real Decreto 4/2019.",b:"Real Decreto 785/2021.",c:"Real Decreto 13/2018.",d:"Real Decreto 587/2021."},correct:"b",why:{b:"El control de la explotación de las autorizaciones VTC se regula en el Real Decreto 785/2021."}},
{n:152,q:"El Real Decreto 785/2021, sobre control de la explotación de las autorizaciones de arrendamiento de vehículos con conductor (VTC) exige que los titulares de estas autorizaciones comuniquen a la administración por vía electrónica...",o:{a:"El nombre y número de identificación fiscal del arrendador.",b:"Lugar, fecha y hora de celebración del contrato.",c:"En caso de que el servicio se inicie y finalice en el mismo lugar, el punto de recorrido más alejado de dicho lugar.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El RD 785/2021 exige comunicar el nombre e identificación fiscal del arrendador (a), lugar, fecha y hora del contrato (b) y, cuando el servicio empiece y acabe en el mismo lugar, el punto más alejado del recorrido (c)."}},
{n:153,q:"Los distintivos que deben llevar los vehículos destinados al arrendamiento con conductor (VTC) en el ámbito de la Comunitat Valenciana, están regulados en...",o:{a:"Real Decreto 785/2021",b:"Real Decreto 13/2018.",c:"Decreto Ley 4/2019.",d:"Orden 12/2016 de la Consellería de Vivienda, Obras Públicas y Vertebración del Territorio."},correct:"d",why:{d:"Los distintivos de los vehículos VTC en la Comunitat Valenciana están regulados en la Orden 12/2016 de la Consellería de Vivienda, Obras Públicas y Vertebración del Territorio."}},
{n:154,q:"La autorización de transporte público de mercancías habilita:",o:{a:"Para realizar transportes de esta clase, en las condiciones señaladas en el artículo 54 de la Ley 16/1987, de Ordenación de los Transportes Terrestres",b:"Para intermediar en la contratación de esta clase de transportes conforme a lo previsto en el art. 119.1 de la Ley 16/1987, de Ordenación de los Transportes Terrestres.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La autorización de transporte público de mercancías habilita tanto para realizar transportes (a) como para intermediar en su contratación (b), siendo ambas habilitaciones correctas."}},
{n:155,q:"Durante el transporte de mercancías, únicamente podrán ocupar el vehículo personas distintas a su conductor y tripulación:",o:{a:"Cuando así lo posibilite su permiso de circulación.",b:"Cuando su transporte no dé lugar a retribución alguna.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas condiciones deben cumplirse simultáneamente: que el permiso de circulación lo permita (a) y que el transporte no genere retribución (b)."}},
{n:156,q:"En los transportes públicos de mercancías por carretera debe formalizarse un documento administrativo de control por cada envío, con formato de libre elección y que deberá llevarse a bordo del vehículo, acompañando a las mercancías en su desplazamiento, debiendo contener, como mínimo:",o:{a:"Nombre, NIF y domicilio del cargador y del transportista efectivo.",b:"Lugar de origen y destino del envío, así como naturaleza y peso de la mercancía transportada.",c:"Fecha de realización del transporte y matrículas del vehículo tractor, remolque y semirremolque, en su caso.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El documento administrativo de control del transporte de mercancías debe contener como mínimo: datos del cargador y transportista (a), origen, destino, naturaleza y peso (b) y fecha y matrículas (c)."}},
{n:157,q:"Según el artículo 100 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, los transportes privados pueden ser:",o:{a:"Privados particulares o privados complementarios.",b:"Privados permanentes, privados particulares o privados discrecionales.",c:"Privados permanentes o privados complementarios.",d:"Privados discrecionales o privados particulares."},correct:"a",why:{a:"El art.100 de la Ley 16/1987 clasifica los transportes privados en particulares y complementarios, sin incluir categorías como discrecionales o permanentes dentro de los privados."}},
{n:158,q:"De conformidad con lo establecido en el art.101 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, para que un transporte pueda considerarse privado particular:",o:{a:"Debe estar destinado a satisfacer las necesidades de desplazamiento de carácter personal o doméstico de su titular y allegados.",b:"Debe obtener una autorización administrativa o tarjeta de transporte del tipo VPP.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El transporte privado particular debe destinarse a satisfacer necesidades personales o domésticas del titular y sus allegados; no requiere autorización del tipo VPP."}},
{n:159,q:"De conformidad con lo establecido en el art.101 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, para que un transporte pueda considerarse privado particular:",o:{a:"Debe realizarse sin intermediarios ni representantes.",b:"Debe realizarse en vehículos cuyo número de plazas o capacidad de carga no exceda de los límites fijados reglamentariamente.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Para ser privado particular, el transporte debe realizarse en vehículos cuyo número de plazas o capacidad de carga no supere los límites reglamentariamente establecidos."}},
{n:160,q:"De conformidad con lo establecido en la Ley 16/1987, de Ordenación de los Transportes Terrestres, los transportes privados particulares:",o:{a:"Necesitan autorización administrativa del tipo VPC.",b:"Necesitan autorización administrativa del tipo VPP.",c:"Necesitan autorización administrativa del tipo XPP.",d:"No necesitan autorización administrativa."},correct:"d",why:{d:"Los transportes privados particulares no requieren autorización administrativa, a diferencia de los privados complementarios que sí la precisan."}},
{n:161,q:"Según el artículo 102 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, los transportes que llevan a cabo empresas u otras entidades, cuyo objeto no es transportar, como complemento necesario de su actividad principal, se denominan:",o:{a:"Privados particulares.",b:"Privados complementarios.",c:"Privados auxiliares.",d:"Privados coadyuvantes."},correct:"b",why:{b:"Los transportes privados complementarios son los realizados por empresas cuyo objeto principal no es el transporte, siendo este un complemento necesario de su actividad principal."}},
{n:162,q:"Según el artículo 102 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, para que el transporte de mercancías pueda considerarse como privado complementario, es preciso:",o:{a:"Que éstas pertenezcan a la empresa o haber sido vendidas, compradas, dadas o tomadas en alquiler, producidas, extraídas, transformadas o reparadas por ella.",b:"Que la empresa no tenga un volumen de negocio superior a los 3 millones de euros.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Para que el transporte de mercancías sea privado complementario, las mercancías deben pertenecer a la empresa o haber sido objeto de alguna de las operaciones indicadas por ella; no existe límite de volumen de negocio."}},
{n:163,q:"Según el artículo 102 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, para que el transporte de viajeros pueda considerarse como privado complementario, es preciso:",o:{a:"Que los usuarios sean trabajadores adscritos a la empresa u otras personas que asistan a éstos.",b:"Que los vehículos empleados sean adaptados para este tipo de servicio.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Para que el transporte de viajeros sea privado complementario, los usuarios deben ser trabajadores de la empresa o personas que asistan a tales trabajadores; no se exige que los vehículos estén especialmente adaptados."}},
{n:164,q:"Según el artículo 102 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, para que un transporte pueda considerarse como privado complementario:",o:{a:"El origen o el destino del transporte debe ser uno de los lugares en que la empresa desarrolle trabajos relacionados con su actividad principal.",b:"Los vehículos y conductores utilizados deben hallarse integrados en la organización de la empresa y contar con las habilitaciones preceptivas.",c:"El transporte no podrá ser contratado ni facturado de forma independiente.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres condiciones son necesarias para que el transporte sea privado complementario: origen/destino vinculado a la actividad principal (a), vehículos y conductores integrados en la empresa (b) y no contratación ni facturación independiente (c)."}},
{n:165,q:"De conformidad con lo establecido en el artículo 103 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, señale la afirmación incorrecta:",o:{a:"Como regla general, las autorizaciones de transporte privado complementario deberán domiciliarse en el lugar en que su titular tenga su domicilio fiscal.",b:"Los transportes privados complementarios no precisan autorización administrativa.",c:"La realización de transportes privados complementarios estará supeditada a la posesión de una autorización que habilite para ello.",d:"No será necesaria la previa obtención de autorización para realizar determinadas modalidades de transporte privado complementario."},correct:"b",why:{b:"La opción b) es incorrecta: los transportes privados complementarios SÍ precisan en general autorización administrativa, aunque existen determinadas modalidades exentas (opción d)."}},
{n:166,q:"De conformidad con lo establecido en el artículo 103 de la Ley 16/1987, de Ordenación de los Transportes Terrestres, estarán exentos de autorización administrativa previa:",o:{a:"Los transportes oficiales y los transportes de viajeros que se realicen en vehículos turismo, salvo que se trate de transporte sanitario.",b:"Los transportes de mercancías que se realicen en vehículos cuya MMA no supere las 3,5 Tm.",c:"Los transportes funerarios, que podrán realizarse libremente en todo el territorio nacional, con independencia de su origen o recorrido.",d:"Todos los transportes descritos en las respuestas anteriores."},correct:"d",why:{d:"Los tres tipos están exentos de autorización previa conforme al art.103: transportes oficiales y en turismo salvo sanitario (a), mercancías en vehículos hasta 3,5 Tm (b) y transportes funerarios (c)."}},
{n:167,q:"De conformidad con lo establecido en la Ley 16/1987, de Ordenación de los Transportes Terrestres, los vehículos que realicen transporte privado complementario:",o:{a:"Deben ser propiedad de las empresas o establecimientos que realizan el transporte, debiendo estar matriculados a nombre de éstas.",b:"Deben ir conducidos por el personal propio de la empresa o establecimiento.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas condiciones son exigibles: los vehículos deben ser propiedad de la empresa y matriculados a su nombre (a), y deben ser conducidos por personal propio (b)."}},
{n:168,q:"De conformidad con lo establecido en la Ley 16/1987, de Ordenación de los Transportes Terrestres, los transportes oficiales para el desplazamiento de personas o mercancías expedidos por la actividad administrativa de los órganos de la Administración:",o:{a:"Tienen la consideración de transportes privados particulares.",b:"No están sujetos a autorización administrativa.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"Los transportes oficiales no están sujetos a autorización administrativa; sin embargo, tienen la consideración de transportes privados complementarios, no particulares, por lo que la opción b) es la única correcta."}},
{n:169,q:"El transporte escolar y de menores se encuentra regulado:",o:{a:"En el RD 443/2001.",b:"En el RD 343/2001.",c:"En el RD 344/2001.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"El transporte escolar y de menores está regulado en el Real Decreto 443/2001."}},
{n:170,q:"El Real Decreto 443/2001 es de aplicación:",o:{a:"A los transportes públicos regulares de uso especial de escolares por carretera, cuando al menos la tercera parte, o más, de los alumnos transportados tuviera una edad inferior a los 16 años, en el momento de comienzo del curso escolar.",b:"A aquellas expediciones de transportes públicos regulares de viajeros de uso general por carretera en la que la mitad, o más de las plazas del vehículo hayan sido previamente reservadas para viajeros menores de 16 años.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El RD 443/2001 se aplica tanto a los transportes regulares de uso especial escolar con al menos un tercio de menores de 16 años (a) como a los regulares de uso general con la mitad de plazas reservadas para menores de 16 años (b)."}},
{n:171,q:"El Real Decreto 443/2001 es de aplicación:",o:{a:"A los transportes públicos discrecionales de viajeros en autobús, cuando tres cuartas partes, o más, de los viajeros sean menores de 16 años.",b:"A los transportes privados particulares de viajeros por carretera, cuando la tercera parte o más, de los viajeros sean menores de 16 años.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El RD 443/2001 se aplica a los transportes discrecionales en autobús cuando al menos las 3/4 partes de los viajeros sean menores de 16 años."}},
{n:172,q:"El Real Decreto 443/2001 es de aplicación:",o:{a:"A los transportes públicos discrecionales de viajeros en autobús, cuando tres cuartas partes, o más, de los viajeros sean menores de 18 años.",b:"A los transportes privados complementarios de viajeros por carretera, cuando la tercera parte, o más, de los viajeros sean menores de 16 años.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"b",why:{b:"El RD 443/2001 se aplica a los transportes privados complementarios cuando al menos 1/3 de los viajeros sean menores de 16 años; en discrecionales en autobús el umbral es 3/4 de menores de 16 (no 18) años."}},
{n:173,q:"Solo podrán realizar transporte escolar:",o:{a:"Las empresas que cuenten con concesión o autorización administrativa que les habilite para llevar a cabo el transporte regular o discrecional que en cada caso se trate.",b:"Los particulares que cuenten con autorizaciones específicas de la Consellería o Ministerio competente en materia de transportes, siempre que acrediten haber depositado las fianzas establecidas en la Ley y demuestren que están realizando actividades de transporte de manera ininterrumpida en los quince años anteriores a la fecha de inicio del curso escolar de que se trate.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Solo pueden realizar transporte escolar las empresas con concesión o autorización administrativa habilitante para el transporte regular o discrecional correspondiente."}},
{n:174,q:"Respecto al transporte escolar y de menores, indique la respuesta incorrecta:",o:{a:"Cuando se realiza transporte escolar es obligatoria la presencia de un acompañante en todo caso.",b:"Para realizar servicios de transporte escolar es requisito indispensable que los vehículos destinados a tal fin hayan superado favorablemente una inspección técnica en una estación ITV, que versará sobre el cumplimiento de los requisitos técnicos exigibles.",c:"Cuando se realiza transporte escolar con acompañante, éste debe ocupar plaza en las inmediaciones de la puerta de servicio central o trasera.",d:"Cuando se incumple la obligación de llevar acompañante en un transporte escolar, el responsable es el transportista."},correct:"a",why:{a:"La opción a) es incorrecta: el acompañante no es obligatorio en todo caso; solo se requiere en supuestos específicos determinados por el RD 443/2001 (tipo de transporte y porcentaje de menores)."}},
{n:175,q:"Durante la realización del transporte escolar será obligatoria la presencia a bordo del vehículo de, al menos una persona mayor de edad, que conozca los mecanismos de seguridad del vehículo y que será la encargada del cuidado de los menores durante el transporte y de las operaciones de acceso y abandono del vehículo de éstos:",o:{a:"Siempre que se transporten alumnos de Centros de Educación Especial.",b:"Cuando al menos el 50% de los viajeros sean menores 14 años.",c:"Cuando, tratándose de transportes discrecionales en autobús, las dos terceras partes de los viajeros sean menores de 16 años.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"Es obligatorio el acompañante siempre que se transporten alumnos de Centros de Educación Especial, conforme al RD 443/2001."}},
{n:176,q:"Durante la realización del transporte escolar será obligatoria la presencia a bordo del vehículo de, al menos, una persona mayor de edad, que conozca los mecanismos de seguridad del vehículo y que será la encargada del cuidado de los menores durante el transporte y de las operaciones de acceso y abandono del vehículo de éstos:",o:{a:"En los transportes públicos discrecionales de viajeros en autobús, en los que las ¾ partes, o más, de los viajeros, sean menores de 16 años.",b:"Cuando tratándose de transportes privados complementarios de viajeros por carretera, en los que la tercera parte o más de los viajeros sean menores de 16 años, el origen o destino del transporte sea distinto del domicilio de los menores o del centro docente donde cursan sus estudios.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambos supuestos exigen acompañante: discrecionales en autobús con 3/4 de menores de 16 años (a) y privados complementarios con 1/3 de menores de 16 cuando el origen/destino difiere del domicilio o centro escolar (b)."}},
{n:177,q:"De conformidad con lo establecido en el art.8 del Real Decreto 443/2001, durante el transporte escolar y de menores el acompañante deberá ocupar plaza:",o:{a:"En las inmediaciones de la puerta de servicio delantera.",b:"En las inmediaciones de la puerta de servicio central o trasera.",c:"Junto al conductor.",d:"En cualquier parte del vehículo que se encuentre cerca de una de las puertas de servicio."},correct:"b",why:{b:"El acompañante en el transporte escolar debe ocupar plaza en las inmediaciones de la puerta de servicio central o trasera, conforme al art.8 del RD 443/2001."}},
{n:178,q:"De conformidad con lo establecido en el Real Decreto 443/2001, el responsable de realizar transporte escolar sin acompañante, en aquellos casos en que sea obligatorio, será:",o:{a:"El transportista.",b:"El transportista y subsidiariamente, la entidad organizadora del servicio.",c:"La entidad organizadora del servicio.",d:"El transportista, salvo que pruebe que no le correspondía a él aportar el acompañante."},correct:"a",why:{a:"El responsable de realizar transporte escolar sin acompañante cuando es obligatorio es el transportista, conforme al RD 443/2001."}},
{n:179,q:"Durante la realización del transporte escolar será obligatoria la presencia a bordo del vehículo de, al menos, una persona mayor de edad, que conozca los mecanismos de seguridad del vehículo y que será la encargada del cuidado de los menores durante el transporte y de las operaciones de acceso y abandono del vehículo de éstos:",o:{a:"En cualquier tipo de transporte realizado en autobús, cuando al menos el 50% de los viajeros sean menores de 12 años.",b:"Cuando, tratándose de transportes discrecionales en autobús, las tres cuartas partes de los viajeros sean menores de 16 años.",c:"En los dos supuestos descritos en las letras a y b anteriores.",d:"En ninguno de los supuestos de las letras a y b."},correct:"c",why:{c:"Se exige acompañante en los dos supuestos: cualquier autobús con 50% de menores de 12 años (a) y discrecionales en autobús con 3/4 de menores de 16 años (b)."}},
{n:180,q:"Con norma general y de conformidad con lo establecido en el art.3 del RD. 443/2001, para transporte escolar solo pueden utilizarse vehículos que, al inicio del curso escolar, no superen:",o:{a:"Los 15 años de antigüedad.",b:"Los 10 años de antigüedad.",c:"Los 16 años de antigüedad.",d:"Los 12 años de antigüedad."},correct:"b",why:{b:"Con carácter general, los vehículos de transporte escolar no pueden superar los 10 años de antigüedad al inicio del curso escolar, conforme al art.3 del RD 443/2001."}},
{n:181,q:"Con norma general y de conformidad con lo establecido en el art.3 del RD. 443/2001, para transporte escolar solo pueden utilizarse vehículos que, al inicio del curso escolar, no superen los 10 años de antigüedad:",o:{a:"Contados desde su primer año de ejercicio en esa actividad.",b:"La antigüedad máxima es de 12 años.",c:"Contados desde su primera matriculación.",d:"La antigüedad máxima es de 15 años."},correct:"c",why:{c:"Los 10 años de antigüedad se computan desde la primera matriculación del vehículo, no desde su primer año en el servicio escolar."}},
{n:182,q:"De conformidad con lo establecido en el art.3 del RD. 443/2001, no podrán destinarse a la realización de transporte escolar, vehículos con una antigüedad superior a:",o:{a:"15 años.",b:"16 años.",c:"12 años.",d:"10 años."},correct:"b",why:{b:"Conforme al art.3 del RD 443/2001, no pueden destinarse al transporte escolar vehículos con una antigüedad superior a 16 años, aunque con carácter general el límite es de 10 años."}},
{n:183,q:"De conformidad con lo establecido en el art.3 del RD. 443/2001, la realización de transporte escolar con vehículos que tengan una antigüedad superior a 10 años:",o:{a:"No está permitida.",b:"Está permitida si los vehículos no superan los 16 años de antigüedad y se acredita que venían dedicándose con anterioridad a la realización de este tipo de transporte.",c:"Está permitida si dichos vehículos superan una inspección técnica extraordinaria, que acredite que cumplen los requisitos técnicos exigidos.",d:"Está prohibida, salvo que se acredite que se trata de la sustitución de otro vehículo afectado por accidente o avería, mientras se subsanan sus deficiencias y siempre que la duración del transporte no exceda de 15 días."},correct:"b",why:{b:"Es posible usar vehículos de más de 10 años para transporte escolar si no superan los 16 años y se acredita que venían realizando este tipo de transporte con anterioridad."}},
{n:184,q:"De conformidad con lo establecido en el art.4 del RD. 443/2001, los vehículos que pretendan realizar servicios de transporte escolar:",o:{a:"Deben superar favorablemente una inspección técnica específica.",b:"Deben estar homologados como vehículos de categoría M.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Los vehículos de transporte escolar deben superar una inspección técnica específica (a) y estar homologados como vehículos de categoría M (b), siendo ambos requisitos exigibles."}},
{n:185,q:"De conformidad con lo establecido en el RD. 443/2001, respecto a las condiciones técnicas de los vehículos dedicados al transporte escolar, indique la respuesta incorrecta:",o:{a:"Los bordes de los escalones serán de color negro o gris oscuro.",b:"El piso del vehículo no podrá ser deslizante.",c:"La abertura practicable de las ventanas será, como máximo, del tercio superior de las mismas.",d:"El asiento del conductor estará protegido por una pantalla transparente."},correct:"a",why:{a:"La opción a) es incorrecta: los bordes de los escalones deben ser de colores vivos (no negro o gris oscuro) para mayor visibilidad y seguridad de los menores."}},
{n:186,q:"De conformidad con lo establecido en el RD. 443/2001, respecto a las condiciones técnicas de los vehículos dedicados al transporte escolar, indique la respuesta incorrecta:",o:{a:"Deben estar dotados de martillos rompecristales y chalecos salvavidas, con instrucciones de uso en caso de accidente o caída al agua.",b:"Las puertas de servicio serán del tipo \"operado por el conductor\" y lo bordes de los escalones serán de colores vivos.",c:"Deben estar dotados de dispositivo luminoso con señal de emergencia.",d:"Deben estar provistos de extintores y de botiquín de primeros auxilios."},correct:"a",why:{a:"La opción a) es incorrecta: no se exigen chalecos salvavidas en los vehículos de transporte escolar terrestre; sí se exigen martillos rompecristales y dispositivos de emergencia."}},
{n:187,q:"De conformidad con lo establecido en el RD. 443/2001, respecto a las condiciones técnicas de los vehículos dedicados al transporte escolar, indique la respuesta incorrecta:",o:{a:"En las salidas de emergencia debe figurar la inscripción \"Salida de emergencia\" o \"Salida de Socorro\", de manera visible desde el interior y el exterior.",b:"Los depósitos de carburante deben estar separados más de 60 centímetros de la parte delantera del vehículo.",c:"Los asientos enfrentados a pasillos que hayan de ser ocupados por menores de 16 años deberán disponer de cinturones de seguridad debidamente homologados.",d:"Deben estar provistos de tacógrafo en todo caso."},correct:"d",why:{d:"La opción d) es incorrecta: los vehículos de transporte escolar no deben llevar tacógrafo en todo caso; su instalación depende de lo que exija la normativa vigente según el tipo de vehículo y servicio."}},
{n:188,q:"De conformidad con lo establecido en el RD. 443/2001, respecto a las condiciones técnicas de los vehículos dedicados al transporte escolar, indique la afirmación correcta:",o:{a:"Deben contar con protección para los dispositivos de apertura de las puertas.",b:"Deben ir provistos de cinturones de seguridad o dispositivos de retención homologados, en los términos previstos en el Reglamento General de Circulación.",c:"Contarán con salidas de emergencia señalizadas y todas las puertas deben tener un dispositivo que avise al conductor cuando no estén completamente cerradas.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones son correctas: protección en dispositivos de apertura (a), cinturones homologados (b) y salidas de emergencia señalizadas con aviso de puertas abiertas (c)."}},
{n:189,q:"De conformidad con lo establecido en el RD. 443/2001, respecto a las condiciones técnicas de los vehículos dedicados al transporte escolar, indique la afirmación correcta:",o:{a:"Contarán con dispositivo acústico de señalización de marcha atrás, que debe funcionar sincronizadamente con las luces de marcha atrás del vehículo.",b:"Irán provistos de tacógrafo y limitador de velocidad cuando así lo exija la normativa vigente.",c:"Contarán con dispositivos ópticos que permitan al conductor detectar la presencia de viajeros en los alrededores inmediatos, tanto exteriores como interiores, de las puertas de servicio.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres son correctas: dispositivo acústico sincronizado con luces de marcha atrás (a), tacógrafo y limitador cuando lo exija la normativa (b) y dispositivos ópticos para detectar viajeros en puertas (c)."}},
{n:190,q:"De conformidad con lo establecido en el RD. 443/2001, el distintivo indicativo del transporte de menores:",o:{a:"Puede ser la señal V-10 que figura en el anexo XI del Reglamento General de Vehículos.",b:"Puede ser el especificado en el Real Decreto 443/2001, en cuyo caso, la silueta de la figura no debe estar iluminada más que durante las paradas que el vehículo realice para que los menores lo aborden o lo abandonen.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"El distintivo de transporte de menores puede ser la señal V-10 del RGV (a) o el especificado en el propio RD 443/2001 —con iluminación solo durante las paradas de acceso— (b), siendo válidas ambas opciones."}},
{n:191,q:"De conformidad con lo establecido en el RD. 443/2001, respecto al distintivo indicativo del transporte de menores:",o:{a:"La señal debe colocarse dentro del vehículo, en la parte frontal y posterior del mismo, de manera que resulte visible desde el exterior.",b:"Debe ser de material indeleble que resista al fuego por un tiempo mínimo de quince minutos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El distintivo debe colocarse en el interior del vehículo, en la parte frontal y posterior, de forma que resulte visible desde el exterior; el requisito del material resistente al fuego no se menciona en el RD 443/2001."}},
{n:192,q:"De conformidad con lo establecido en el RD. 443/2001, los itinerarios y horarios de transporte escolar que tengan origen o destino en el Centro de Enseñanza, se establecerán teniendo en cuenta que el tiempo máximo de permanencia de los alumnos en el vehículo deberá ser inferior a:",o:{a:"1 hora para cada sentido del viaje.",b:"2 horas para cada sentido del viaje.",c:"1 hora y 30 minutos para cada sentido del viaje.",d:"Todas las respuestas anteriores son incorrectas."},correct:"a",why:{a:"El tiempo máximo de permanencia de los alumnos en el vehículo de transporte escolar debe ser inferior a 1 hora para cada sentido del viaje."}},
{n:193,q:"De conformidad con lo establecido en el RD. 443/2001, es obligación de toda entidad organizadora de transporte escolar y de menores:",o:{a:"Suscribir un seguro que cubra de forma ilimitada su responsabilidad civil por los daños que puedan sufrir los ocupantes de los vehículos en los que se realicen, con independencia de los que sean obligatorios según la legislación vigente.",b:"Establecer convenios de colaboración con centros docentes públicos y privados para la realización de otros transportes que resulten exigibles según la normativa vigente.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"La entidad organizadora debe suscribir un seguro de responsabilidad civil ilimitada; el establecimiento de convenios con centros docentes no es una obligación expresa del RD 443/2001."}},
{n:194,q:"Respecto al transporte de mercancías peligrosas, señale la afirmación incorrecta:",o:{a:"Se regula mediante normas específicas que están contenidas en el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) aprobado en Ginebra el 30 de septiembre de 1957 y sus sucesivas enmiendas.",b:"Los transportes que se realicen íntegramente dentro de territorio español deben tener en cuenta las especialidades recogidas en el Anejo I del Real Decreto 97/2014, de 14 de febrero.",c:"La carta de porte debe ser conforme al modelo obligatorio diseñado para la Unión europea.",d:"Este tipo de transportes se puede realizar en tres modalidades: a granel, bultos y cisternas."},correct:"c",why:{c:"La opción c) es incorrecta: la carta de porte en el transporte de mercancías peligrosas no tiene un modelo obligatorio único para la UE; su formato es de libre elección."}},
{n:195,q:"Respecto a las modalidades de transporte de mercancías peligrosas, señale la afirmación correcta:",o:{a:"En la modalidad de transporte de \"Bultos\" las mercancías están envasadas en cajas, botellas, jerricanas o bidones.",b:"La modalidad de transporte en \"Cisternas\" sirve para transportar gases o líquidos sin envasar.",c:"Es modalidad \"a granel\" cuando se transportan sólidos sin envasar, asumiendo las funciones de envase el propio vehículo.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres modalidades son correctas: Bultos con envases (a), Cisternas para gases o líquidos sin envasar (b) y Granel para sólidos sin envasar usando el vehículo como envase (c)."}},
{n:196,q:"Excepto en lo relativo a la estanqueidad de los envases utilizados, no es aplicable el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR):",o:{a:"En el transporte realizado por particulares, cuando las materias estén acondicionadas para la venta al por menor y su uso sea doméstico, de ocio o deportivo, con un límite de 60 litros o kg por envase, o de 240 kg o litros por unidad de transporte.",b:"En el transporte realizado por empresas de modo accesorio a su actividad principal, siempre que no exceda de 450 litros por envase, ni las cantidades máximas establecidas para cada mercancía.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas excepciones a la aplicación del ADR son correctas: transporte por particulares con uso doméstico/ocio (a) y transporte accesorio por empresas dentro de los límites indicados (b)."}},
{n:197,q:"Con respecto a los documentos que obligatoriamente debe portar un vehículo que transporte mercancías peligrosas, indique la respuesta incorrecta:",o:{a:"Carta de porte.",b:"Instrucciones escritas.",c:"Un documento de identificación con fotografía por cada miembro de la tripulación.",d:"Un documento que acredite que los envases utilizados para contener las materias peligrosas están homologados conforme a la Norma UNE 765/22/ENV."},correct:"d",why:{d:"La opción d) es incorrecta: no es obligatorio portar un documento que acredite la homologación de los envases conforme a la Norma UNE 765/22/ENV; los documentos obligatorios son la carta de porte, las instrucciones escritas y la identificación de la tripulación."}},
{n:198,q:"Los vehículos que transporten mercancías peligrosas deben ir provistos de una carta de porte, cuyo formato será:",o:{a:"De libre edición.",b:"El contenido en el Anejo I del RD. 97/2014.",c:"El que se contiene en la Norma UNE 765/22/ENV.",d:"El que reglamentariamente se determine."},correct:"a",why:{a:"La carta de porte en el transporte de mercancías peligrosas es de libre edición; no existe un formato único obligatorio."}},
{n:199,q:"Toda operación de transporte de mercancías peligrosas estará acompañada de una carta de porte que será entregada por el expedidor al conductor del vehículo, donde constará:",o:{a:"El nombre de la mercancía transportada, los números de identificación de la materia y la cantidad total.",b:"El nombre y dirección del expedidor.",c:"El nombre y dirección del destinatario.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"La carta de porte de mercancías peligrosas debe recoger: nombre, número de identificación y cantidad (a), datos del expedidor (b) y datos del destinatario (c)."}},
{n:200,q:"En las instrucciones escritas que deben llevar aquellos vehículos que transporten mercancías peligrosas debe constar:",o:{a:"La naturaleza del peligro y las medidas de seguridad necesarias.",b:"Las medidas a tomar en caso de deterioro de los embalajes.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Las instrucciones escritas deben incluir la naturaleza del peligro y las medidas de seguridad (a) y las medidas ante el deterioro de los embalajes (b), siendo ambas correctas."}},
{n:201,q:"En las instrucciones escritas que deben llevar aquellos vehículos que transporten mercancías peligrosas debe constar:",o:{a:"Las disposiciones a tomar con las personas posiblemente afectadas.",b:"Las medidas a tomar en caso de incendio o accidente.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Las instrucciones escritas deben incluir las disposiciones a tomar con las personas afectadas (a) y las medidas en caso de incendio o accidente (b), siendo ambas obligatorias."}},
{n:202,q:"El certificado de aprobación del vehículo es obligatorio:",o:{a:"En el transporte de explosivos.",b:"En el transporte realizado en vehículos con cisterna fija de capacidad superior a 500 litros.",c:"En el transporte realizado en vehículos con cisterna desmontable con capacidad superior a 2.000 litros.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El certificado de aprobación del vehículo es obligatorio en el transporte de explosivos; para cisternas fijas el umbral es superior a 1.000 litros, no 500."}},
{n:203,q:"El certificado de aprobación del vehículo es obligatorio:",o:{a:"En el transporte de lubricantes.",b:"En el transporte realizado en vehículos con cisterna fija de capacidad superior a 1.000 litros.",c:"En el transporte realizado en vehículos con cisterna desmontable con capacidad superior a 2.000 litros.",d:"En transportes que excedan del ámbito de una comunidad autónoma."},correct:"b",why:{b:"El certificado de aprobación del vehículo es obligatorio en el transporte realizado con cisterna fija de capacidad superior a 1.000 litros."}},
{n:204,q:"El certificado de aprobación del vehículo es obligatorio:",o:{a:"En el transporte de explosivos.",b:"En el transporte realizado en vehículos con cisterna fija de capacidad superior a 1.000 litros.",c:"En el transporte realizado en vehículos con cisterna desmontable con capacidad superior a 3.000 litros.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"El certificado de aprobación es obligatorio en los tres supuestos: transporte de explosivos (a), cisterna fija superior a 1.000 litros (b) y cisterna desmontable superior a 3.000 litros (c)."}},
{n:205,q:"Para conducir vehículos que transporten mercancías peligrosas se exige un certificado de formación del conductor, cuyo período de vigencia es de:",o:{a:"3 años.",b:"5 años.",c:"6 años.",d:"7 años."},correct:"b",why:{b:"El certificado de formación del conductor para el transporte de mercancías peligrosas tiene un período de vigencia de 5 años."}},
{n:206,q:"Para conducir vehículos que transporten mercancías peligrosas se exige un certificado de formación del conductor...",o:{a:"Que por si solo no autoriza a conducir si no va acompañado del permiso de conducción requerido para el vehículo de que se trate.",b:"Que debe ser renovado anualmente.",c:"Que supone la realización de un curso previo de 240 horas.",d:"Todas las respuestas anteriores son correctas."},correct:"a",why:{a:"El certificado de formación para mercancías peligrosas no autoriza por sí solo a conducir; debe ir acompañado del permiso de conducción correspondiente al tipo de vehículo."}},
{n:207,q:"Para conducir vehículos que transporten mercancías peligrosas, el certificado de formación puede ser:",o:{a:"De cuatro tipos: básico, cisternas, radioactivas y explosivas.",b:"De carácter permanente o sometido a renovación temporal.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El certificado de formación para mercancías peligrosas es de cuatro tipos: básico, cisternas, radioactivas y explosivas."}},
{n:208,q:"Para conducir vehículos que transporten mercancías peligrosas, el certificado de formación puede ser:",o:{a:"Básico, para transporte de mercancías peligrosas en bultos, excepto radiactivas y explosivos.",b:"De \"Cisternas, para todo tipo de transporte en ellas, salvo radiactivas y explosivos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Existen certificados básico (para bultos excepto radioactivos y explosivos) (a) y de cisternas (para todo transporte en cisterna excepto radioactivos y explosivos) (b), siendo ambos correctos."}},
{n:209,q:"Respecto al transporte de mercancías peligrosas, indique la afirmación correcta:",o:{a:"Los conductores de estos vehículos no pueden ingerir bebidas alcohólicas desde, al menos, 6 horas antes de iniciar el transporte.",b:"Los conductores de estos vehículos no podrán superar los 0,15 mg de alcohol por litro de aire espirado, o su equivalente, es decir 0,3 gramos de alcohol por litro de sangre.",c:"Los miembros de la tripulación deben acreditar documentalmente que han recibido la formación adecuada para llevar a cabo aquellas operaciones que se les hayan encomendado.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones son correctas: prohibición de alcohol 6 horas antes (a), límite de 0,15 mg/l en aire espirado (b) y acreditación documental de formación de la tripulación (c)."}},
{n:210,q:"Con respecto al conductor de un transporte de mercancías peligrosas, indique la respuesta correcta:",o:{a:"Tiene prohibido abrir los bultos de las mercancías peligrosas que transporte.",b:"No puede superar los 50 años edad, salvo que acredite que viene dedicándose a la realización de este tipo de transporte con anterioridad.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"El conductor de mercancías peligrosas tiene prohibido abrir los bultos de la carga que transporta; no existe límite de edad de 50 años para este tipo de transporte."}},
{n:211,q:"En los vehículos que transporten mercancías peligrosas:",o:{a:"Está prohibido fumar, dentro de los mismos y en sus proximidades.",b:"Debe ir un ayudante en determinados casos.",c:"Está prohibido el transporte de viajeros.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres afirmaciones son correctas: prohibición de fumar dentro y en las proximidades (a), obligación de ayudante en determinados casos (b) y prohibición del transporte de viajeros (c)."}},
{n:212,q:"La señalización de los vehículos que transporten mercancías peligrosas:",o:{a:"Estará formada por paneles y luces giratorias amarillo selectivo.",b:"Estará formada por paneles y luces giratorias amarillo auto.",c:"Estará formada por paneles, etiquetas de peligro y luces destellantes de color naranja.",d:"Estará formada por los paneles y etiquetas de peligro que correspondan."},correct:"d",why:{d:"La señalización de los vehículos de mercancías peligrosas se compone de los paneles naranjas y las etiquetas de peligro que correspondan según la clase de mercancía."}},
{n:213,q:"Los paneles de peligro de los vehículos que transporten mercancías peligrosas:",o:{a:"Serán rectangulares de color naranja reflectante con borde negro.",b:"Estarán colocados de forma bien visible, en la parte posterior y exterior del vehículo.",c:"Deben ser indelebles y permanecer legibles después de un incendio de una duración de 15 minutos.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres características son correctas: paneles rectangulares naranjas con borde negro (a), colocados visiblemente en la parte posterior y exterior (b) e indelebles resistentes a incendio de 15 min (c)."}},
{n:214,q:"Los paneles de los vehículos que transporten mercancías peligrosas:",o:{a:"Indican que el vehículo lleva mercancías peligrosas sin especificar.",b:"No son obligatorios en vías urbanas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"d",why:{d:"Ambas afirmaciones son incorrectas: los paneles identifican también el tipo de peligro y la materia (no solo que lleva mercancías sin especificar) y son obligatorios también en vías urbanas."}},
{n:215,q:"Respecto al transporte de mercancías peligrosas, indique la respuesta incorrecta:",o:{a:"Los números que figuran en la parte superior de los paneles de peligro de los vehículos que transportan dichas mercancías indican el peligro.",b:"Los vehículos cisterna que transporten mercancías peligrosas no necesitan llevar etiquetas de peligro.",c:"Los números que figuran en la parte inferior de los paneles de peligro de los vehículos que transportan dichas mercancías identifican la materia.",d:"Los vehículos que transportan mercancías peligrosas con MMA superior a 3.500 kg deben estar dotados de tacógrafo."},correct:"b",why:{b:"La opción b) es incorrecta: los vehículos cisterna que transporten mercancías peligrosas SÍ deben llevar etiquetas de peligro."}},
{n:216,q:"Los paneles de peligro que deben portar los vehículos que transporten mercancías peligrosas:",o:{a:"En su parte superior llevarán inscritas las cifras que compongan el código de peligro de la materia transportada.",b:"En la parte inferior llevarán inscritas las cifras que compongan su código de identificación.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Los paneles de peligro llevan en la parte superior el código de peligro (a) y en la parte inferior el código de identificación de la materia (b); ambas afirmaciones son correctas."}},
{n:217,q:"Respecto a los vehículos destinados al transporte de mercancías peligrosas, indique la frase incorrecta:",o:{a:"Deben estar dotados de, al menos, un aparato portátil contra incendios, con capacidad para combatir un incendio del motor, de tal naturaleza que no agrave el incendio de la carga.",b:"Deben llevar dos luces portátiles de color naranja, independientes de la instalación del vehículo.",c:"Deben ir provistos de tacógrafo.",d:"Deberán portar los paneles y etiquetas de peligro que correspondan."},correct:"c",why:{c:"La opción c) es incorrecta: los vehículos de mercancías peligrosas no están obligados a llevar tacógrafo por el mero hecho de transportar dichas mercancías."}},
{n:218,q:"Los vehículos que transporten mercancías peligrosas:",o:{a:"En ningún caso podrán llevar más de un remolque o semirremolque.",b:"No podrán sobrepasar 7 Tm de MMA.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Los vehículos de mercancías peligrosas no pueden llevar más de un remolque o semirremolque; el límite de 7 Tm de MMA no existe como tal en la normativa."}},
{n:219,q:"Toda unidad de transporte de mercancías peligrosas debe estar provista, al menos, de un extintor portátil de 2 Kg. de polvo, adecuado para combatir un incendio del motor o de la cabina y como mínimo adaptado a la inflamabilidad de las clases:",o:{a:"A, B y C.",b:"A, E y H.",c:"B, C y E.",d:"B, C, D y E."},correct:"a",why:{a:"El extintor portátil de 2 kg de polvo debe ser como mínimo apto para las clases de fuego A, B y C."}},
{n:220,q:"Los transportes de mercancías peligrosas realizados en unidades de transporte con masa máxima admisible superior a 7,5 toneladas, deben portar:",o:{a:"Uno o varios extintores con una capacidad mínima total de 12 kg de polvo.",b:"Uno o varios extintores con una capacidad mínima total de 6 Kg de polvo.",c:"Uno o varios extintores con una capacidad mínima total de 8 Kg de polvo.",d:"Uno o varios extintores con una capacidad mínima total de 4 kg. De polvo."},correct:"a",why:{a:"Las unidades de transporte de mercancías peligrosas con MMA superior a 7,5 Tm deben llevar extintores con una capacidad mínima total de 12 kg de polvo."}},
{n:221,q:"Los transportes de mercancías peligrosas realizados en unidades de transporte con masa máxima admisible entre 3,5 y 7,5 toneladas, deben portar:",o:{a:"Uno o varios extintores con una capacidad mínima total de 12 kg de polvo.",b:"Uno o varios extintores con una capacidad mínima total de 6 Kg de polvo.",c:"Uno o varios extintores con una capacidad mínima total de 8 Kg de polvo.",d:"Uno o varios extintores con una capacidad mínima total de 4 kg. De polvo."},correct:"c",why:{c:"Las unidades de transporte de mercancías peligrosas con MMA entre 3,5 y 7,5 Tm deben llevar extintores con capacidad mínima de 8 kg de polvo."}},
{n:222,q:"Los transportes de mercancías peligrosas realizados en unidades de transporte con masa máxima admisible igual o inferior a 3,5 toneladas, deben portar:",o:{a:"Uno o varios extintores con una capacidad mínima total de 12 kg de polvo.",b:"Uno o varios extintores con una capacidad mínima total de 6 Kg de polvo.",c:"Uno o varios extintores con una capacidad mínima total de 8 Kg de polvo.",d:"Uno o varios extintores con una capacidad mínima total de 4 kg. De polvo."},correct:"d",why:{d:"Las unidades de transporte de mercancías peligrosas con MMA igual o inferior a 3,5 Tm deben llevar extintores con capacidad mínima de 4 kg de polvo."}},
{n:223,q:"Cada unidad de transporte de mercancías peligrosas debe ir equipada con:",o:{a:"Un calzo por vehículo de dimensiones apropiadas.",b:"Dos señales de advertencia autoportantes.",c:"Líquido para el lavado de los ojos cuando se transporten determinadas materias.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres son correctas: calzo de dimensiones apropiadas (a), dos señales autoportantes (b) y líquido para lavado de ojos cuando corresponda (c)."}},
{n:224,q:"Cada unidad de transporte de mercancías peligrosas debe ir equipada con:",o:{a:"Un chaleco o ropa fluorescente, un par de guantes protectores, un equipo de protección ocular y un aparato de iluminación portátil por cada miembro que componga la tripulación del vehículo.",b:"Una máscara de evacuación de emergencia por cada miembro de la tripulación cuando se transporten materias provistas de etiquetas de peligro de las clases 2.3 ó 6.1",c:"Una pala, un obturador de entrada al alcantarillado y un recipiente colector cuando se transporten materias sólidas o líquidas con etiquetas de las clases 3, 4.1, 4.3, 8, ó 9.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"Las tres son correctas: EPIs por tripulante (a), máscara de evacuación para clases 2.3/6.1 (b) y pala, obturador y recipiente para clases 3, 4.1, 4.3, 8 o 9 (c)."}},
{n:225,q:"Los vehículos que transporten mercancías peligrosas deberán utilizar los itinerarios que se establezcan, accediendo o abandonando éstos:",o:{a:"Por la entrada o salida más próxima a los lugares de carga o descarga.",b:"Cuando el tráfico sea fluido.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Los vehículos de mercancías peligrosas deben acceder o abandonar los itinerarios establecidos por la entrada o salida más próxima a los lugares de carga o descarga."}},
{n:226,q:"Cuando existan itinerarios coincidentes por autopista, autovía o plataforma desdoblada para ambos sentidos de circulación, los vehículos que transporten mercancías peligrosas:",o:{a:"Deberán seguirlos obligatoriamente, salvo que se hayan establecido restricciones al respecto.",b:"Solo están obligados a seguirlos si así lo impone la naturaleza de la materia transportada.",c:"Deberán seguirlos cuando las condiciones meteorológicas así lo aconsejen.",d:"Solo están obligados a seguirlos en los supuestos establecidos en el Anejo I del RD. 97/2014."},correct:"a",why:{a:"Los vehículos de mercancías peligrosas deben seguir obligatoriamente los itinerarios por autopista o autovía cuando existan, salvo que haya restricciones específicas establecidas al respecto."}},
{n:227,q:"Los vehículos que transporten mercancías peligrosas:",o:{a:"Cuando existan circunvalaciones, variantes o rondas exteriores a las poblaciones deberán utilizarlas inexcusablemente y siempre la más externa, en su caso, al casco urbano.",b:"Únicamente entrarán a la población para realizar carga o descarga y siempre por el acceso más próximo, salvo causas justificadas de fuerza mayor.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas obligaciones son correctas: uso inexcusable de circunvalaciones exteriores (a) y entrada a la población solo para carga/descarga por el acceso más próximo (b)."}},
{n:228,q:"En travesías y vías urbanas los vehículos que transporten mercancías peligrosas:",o:{a:"No pueden superar los 40 Km/hora.",b:"No pueden superar los 30 Km/hora.",c:"No pueden superar los 20 km/hora.",d:"Ninguna de las respuestas anteriores es correcta."},correct:"a",why:{a:"En travesías y vías urbanas los vehículos que transporten mercancías peligrosas no pueden superar los 40 km/hora."}},
{n:229,q:"Como norma general los vehículos destinados al transporte de mercancías peligrosas estacionarán en lugares que ofrezcan las suficientes garantías de seguridad y si lo hacen fuera de éstos:",o:{a:"Deberán estar siempre vigilados.",b:"El vehículo debe tener un mecanismo de control a distancia que emita una señal luminosa y sonora, ante cualquier intento de sabotaje.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"a",why:{a:"Cuando los vehículos de mercancías peligrosas estacionen fuera de los lugares seguros, deberán estar siempre vigilados."}},
{n:230,q:"Cuando un vehículo de transporte de mercancías peligrosas estacione separadamente en un parque de estacionamiento vigilado por un encargado:",o:{a:"Este deberá ser informado de la naturaleza de la carga y del lugar donde se encuentra el conductor.",b:"El estacionamiento se efectuará de forma que la unidad de transporte no pueda ser dañada por otros vehículos.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas son correctas: el encargado debe ser informado de la naturaleza de la carga y la ubicación del conductor (a) y el estacionamiento debe proteger el vehículo de posibles daños (b)."}},
{n:231,q:"Cuando por avería o accidente, un vehículo que transporta mercancías peligrosas no pueda continuar la marcha:",o:{a:"Los miembros de la tripulación adoptarán inmediatamente las medidas que se determinen en las instrucciones escritas.",b:"Los miembros de la tripulación procederán a informar de la situación al teléfono del Centro de Coordinación de Emergencias y a las empresas transportista y expedidora.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ante una avería o accidente, la tripulación debe tanto adoptar las medidas de las instrucciones escritas (a) como informar al Centro de Coordinación de Emergencias y a las empresas (b)."}},
{n:232,q:"Cuando por avería o accidente, un vehículo que transporta mercancías peligrosas no pueda continuar la marcha, los miembros de la tripulación procederán a informar de la situación al teléfono del Centro de Coordinación de Emergencias y a las empresas transportista y expedidora:",o:{a:"Correcto, y si éstos no pudiesen hacerlo, la autoridad o agente más cercano, o el servicio de intervención que hubiese recibido la noticia, se asegurarán de que sean informados los responsables del Centro de Coordinación Operativa de la Comunidad Autónoma establecidos en el correspondiente Plan de Actuación.",b:"Correcto, y si éstos no pudiesen hacerlo, la autoridad o agente más cercano, o el servicio de intervención que hubiese recibido la noticia, se asegurarán de que sean informados los responsables en materia de tráfico y seguridad vial.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"Ambas son correctas: si la tripulación no puede informar, la autoridad o servicio de intervención notificará tanto al Centro de Coordinación Operativa autonómico (a) como a los responsables de tráfico y seguridad vial (b)."}},
{n:233,q:"Quien comunique la avería o accidente de un vehículo que transporta mercancías peligrosas, facilitará:",o:{a:"La localización del suceso, el estado del vehículo implicado y la posible existencia de víctimas,",b:"Los datos sobre las mercancías peligrosas transportadas;",c:"Las condiciones meteorológicas u otras circunstancias que se consideren de interés para valorar los posibles efectos del suceso.",d:"Todas las respuestas anteriores son correctas."},correct:"d",why:{d:"La comunicación de avería o accidente debe incluir: localización, estado del vehículo y víctimas (a), datos de la mercancía peligrosa (b) y condiciones meteorológicas y otras circunstancias relevantes (c)."}},
{n:234,q:"De las actuaciones que realicen las Fuerzas y Cuerpos de Seguridad, como consecuencia de accidentes o incidentes de vehículos de mercancías peligrosas, se remitirá un informe:",o:{a:"A la Dirección General de Tráfico.",b:"A la Dirección General de Protección Civil y Emergencias.",c:"A la Subdelegación del Gobierno.",d:"A todos los organismos citados en las respuestas anteriores."},correct:"b",why:{b:"El informe de las actuaciones de las FCS en accidentes de mercancías peligrosas se remite a la Dirección General de Protección Civil y Emergencias."}},
{n:235,q:"De las actuaciones que realicen las Fuerzas y Cuerpos de Seguridad, como consecuencia de accidentes o incidentes de vehículos de mercancías peligrosas, se remitirá un informe a la Dirección General de Protección Civil y Emergencias:",o:{a:"Que dará traslado del mismo a la Comisión de Coordinación del Transporte de Mercancías Peligrosas.",b:"Que, en caso de que se vean afectados los depósitos de las cisternas o sus equipos, se remitirá un informe fotográfico reflejando su estado a la Comisión de Coordinación del Transporte de Mercancías Peligrosas.",c:"Las respuestas a y b son correctas.",d:"Las respuestas a y b son incorrectas."},correct:"c",why:{c:"La DG de Protección Civil y Emergencias dará traslado del informe a la Comisión de Coordinación (a) y, si hay afectación de depósitos o cisternas, se remitirá también un informe fotográfico a dicha Comisión (b)."}},
{n:236,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 3.",o:{a:"Los gases.",b:"Las materias radioactivas.",c:"Las materias corrosivas.",d:"Los líquidos inflamables."},correct:"d",why:{d:"La Clase 3 del ADR corresponde a los líquidos inflamables."}},
{n:237,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 7.",o:{a:"Los gases.",b:"Las materias radioactivas.",c:"Las materias corrosivas.",d:"Los líquidos inflamables."},correct:"b",why:{b:"La Clase 7 del ADR corresponde a las materias radioactivas."}},
{n:238,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 8.",o:{a:"Los gases.",b:"Las materias radioactivas.",c:"Las materias corrosivas.",d:"Los líquidos inflamables."},correct:"c",why:{c:"La Clase 8 del ADR corresponde a las materias corrosivas."}},
{n:239,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 2.",o:{a:"Los gases.",b:"Las materias radioactivas.",c:"Las materias corrosivas.",d:"Los líquidos inflamables."},correct:"a",why:{a:"La Clase 2 del ADR corresponde a los gases (comprimidos, licuados, disueltos a presión o criogénicos)."}},
{n:240,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 6.2.",o:{a:"Las materias sólidas inflamables, las materias auto reactivas, y las materias explosivas desensibilizadas sólidas.",b:"Las materias infecciosas.",c:"Las materias y objetos explosivos.",d:"Las materias comburentes."},correct:"b",why:{b:"La Clase 6.2 del ADR corresponde a las materias infecciosas."}},
{n:241,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 5.1.",o:{a:"Las materias sólidas inflamables, las materias auto reactivas, y las materias explosivas desensibilizadas sólidas.",b:"Las materias infecciosas.",c:"Las materias y objetos explosivos.",d:"Las materias comburentes."},correct:"d",why:{d:"La Clase 5.1 del ADR corresponde a las materias comburentes (oxidantes)."}},
{n:242,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 4.1.",o:{a:"Las materias sólidas inflamables, las materias auto reactivas, y las materias explosivas desensibilizadas sólidas.",b:"Las materias infecciosas.",c:"Las materias y objetos explosivos.",d:"Las materias comburentes."},correct:"a",why:{a:"La Clase 4.1 del ADR corresponde a las materias sólidas inflamables, las materias autorreactivas y las materias explosivas desensibilizadas sólidas."}},
{n:243,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 1.",o:{a:"Las materias sólidas inflamables, las materias auto reactivas, y las materias explosivas desensibilizadas sólidas.",b:"Las materias infecciosas.",c:"Las materias y objetos explosivos.",d:"Las materias comburentes."},correct:"c",why:{c:"La Clase 1 del ADR corresponde a las materias y objetos explosivos."}},
{n:244,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 4.2.",o:{a:"Las materias que pueden experimentar inflamación espontánea.",b:"Las materias que en contacto con el agua desprenden gases inflamables.",c:"Los peróxidos orgánicos.",d:"Las materias y objetos peligrosos diversos."},correct:"a",why:{a:"La Clase 4.2 del ADR corresponde a las materias que pueden experimentar inflamación espontánea (piroforicas)."}},
{n:245,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 9.",o:{a:"Las materias que pueden experimentar inflamación espontánea.",b:"Las materias que en contacto con el agua desprenden gases inflamables.",c:"Los peróxidos orgánicos.",d:"Las materias y objetos peligrosos diversos."},correct:"d",why:{d:"La Clase 9 del ADR corresponde a las materias y objetos peligrosos diversos, categoría residual que incluye todo lo no clasificado en las clases anteriores."}},
{n:246,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 5.2.",o:{a:"Las materias que pueden experimentar inflamación espontánea.",b:"Las materias que en contacto con el agua desprenden gases inflamables.",c:"Los peróxidos orgánicos.",d:"Las materias y objetos peligrosos diversos."},correct:"c",why:{c:"La Clase 5.2 del ADR corresponde a los peróxidos orgánicos."}},
{n:247,q:"Según el Acuerdo Europeo sobre Transporte Internacional de Mercancías Peligrosas por Carretera (ADR) pertenecen a la Clase 4.3.",o:{a:"Las materias que pueden experimentar inflamación espontánea.",b:"Las materias que en contacto con el agua desprenden gases inflamables.",c:"Los peróxidos orgánicos.",d:"Las materias y objetos peligrosos diversos."},correct:"b",why:{b:"La Clase 4.3 del ADR corresponde a las materias que en contacto con el agua desprenden gases inflamables."}}
];